/* Template-specific starter flows (en, ar, de, es, fr, pt). */
window.CHATORA_TEMPLATE_FLOWS = {"comment-to-dm-starter":{"en":[{"t":"trigger","text":"Comment on a post contains the keyword \"LINK\" or \"PRICE\""},{"t":"msg","text":"(Public reply) Thanks [name]! Check your DMs, I just sent you the details."},{"t":"msg","text":"Hi [name]! Here is the link you asked for: [product link]. Reply \"HELP\" if you want me to pick a size or option for you."},{"t":"tag","text":"Tag: comment-lead"}],"ar":[{"t":"trigger","text":"تعليق على بوست فيه كلمة \"لينك\" أو \"السعر\""},{"t":"msg","text":"(رد علني) شكرًا يا [الاسم]! بصّ على الرسايل الخاصة، بعتلك التفاصيل."},{"t":"msg","text":"أهلاً يا [الاسم]! ده اللينك اللي طلبته: [لينك المنتج]. ابعت \"مساعدة\" لو عايزني أساعدك تختار المقاس أو الخيار."},{"t":"tag","text":"وسم: عميل-من-تعليق"}],"de":[{"t":"trigger","text":"Kommentar unter einem Beitrag enthält das Schlüsselwort „LINK“ oder „PREIS“"},{"t":"msg","text":"(Öffentliche Antwort) Danke [Name]! Schau in deine DMs, ich habe dir gerade die Details geschickt."},{"t":"msg","text":"Hallo [Name]! Hier ist der Link, den du wolltest: [Produktlink]. Antworte „HILFE“, wenn ich dir bei Größe oder Option helfen soll."},{"t":"tag","text":"Tag: kommentar-lead"}],"es":[{"t":"trigger","text":"Comentario en una publicación contiene la palabra clave «ENLACE» o «PRECIO»"},{"t":"msg","text":"(Respuesta pública) ¡Gracias [nombre]! Revisa tus DMs, acabo de enviarte los detalles."},{"t":"msg","text":"¡Hola [nombre]! Aquí está el enlace que pediste: [enlace del producto]. Responde «AYUDA» si quieres que te ayude a elegir talla u opción."},{"t":"tag","text":"Etiqueta: lead-comentario"}],"fr":[{"t":"trigger","text":"Commentaire sur une publication contenant le mot-clé « LIEN » ou « PRIX »"},{"t":"msg","text":"(Réponse publique) Merci [nom] ! Regarde tes DM, je viens de t'envoyer les détails."},{"t":"msg","text":"Bonjour [nom] ! Voici le lien demandé : [lien du produit]. Réponds « AIDE » si tu veux que je t'aide à choisir une taille ou une option."},{"t":"tag","text":"Tag : lead-commentaire"}],"pt":[{"t":"trigger","text":"Comentário em um post contém a palavra-chave «LINK» ou «PREÇO»"},{"t":"msg","text":"(Resposta pública) Obrigado [nome]! Olha suas DMs, acabei de te mandar os detalhes."},{"t":"msg","text":"Olá [nome]! Aqui está o link que você pediu: [link do produto]. Responde «AJUDA» se quiser que eu te ajude a escolher tamanho ou opção."},{"t":"tag","text":"Tag: lead-comentário"}]},"reel-virality-guard":{"en":[{"t":"trigger","text":"New comment on a reel with the campaign keyword"},{"t":"cond","text":"Has this person already received the DM in the last 24 hours?"},{"t":"msg","text":"If not: \"Hi [name], thanks for watching! Here is what you asked for: [link].\""},{"t":"delay","v":10},{"t":"msg","text":"Quick follow-up: \"Did the link open fine? Tell me if you need anything else.\""},{"t":"tag","text":"Tag: reel-lead (skip if duplicate)"}],"ar":[{"t":"trigger","text":"تعليق جديد على ريل فيه كلمة الحملة"},{"t":"cond","text":"هل استلم الشخص ده الرسالة في آخر 24 ساعة؟"},{"t":"msg","text":"لو لأ: \"أهلاً [الاسم]، شكرًا إنك شفت الريل! ده اللي طلبته: [اللينك].\""},{"t":"delay","v":10},{"t":"msg","text":"متابعة سريعة: \"اللينك فتح معاك كويس؟ قولي لو محتاج أي حاجة تانية.\""},{"t":"tag","text":"وسم: عميل-ريل (يتخطى لو مكرر)"}],"de":[{"t":"trigger","text":"Neuer Kommentar unter einem Reel mit dem Kampagnen-Schlüsselwort"},{"t":"cond","text":"Hat diese Person die DM in den letzten 24 Stunden schon erhalten?"},{"t":"msg","text":"Falls nicht: „Hallo [Name], danke fürs Ansehen! Hier ist, was du wolltest: [Link].“"},{"t":"delay","v":10},{"t":"msg","text":"Kurzes Nachfassen: „Hat der Link funktioniert? Sag Bescheid, wenn du noch etwas brauchst.“"},{"t":"tag","text":"Tag: reel-lead (bei Duplikat überspringen)"}],"es":[{"t":"trigger","text":"Nuevo comentario en un reel con la palabra clave de la campaña"},{"t":"cond","text":"¿Esta persona ya recibió el DM en las últimas 24 horas?"},{"t":"msg","text":"Si no: «Hola [nombre], ¡gracias por verlo! Aquí está lo que pediste: [enlace].»"},{"t":"delay","v":10},{"t":"msg","text":"Seguimiento rápido: «¿El enlace abrió bien? Avísame si necesitas algo más.»"},{"t":"tag","text":"Etiqueta: lead-reel (omitir si es duplicado)"}],"fr":[{"t":"trigger","text":"Nouveau commentaire sur un reel avec le mot-clé de la campagne"},{"t":"cond","text":"Cette personne a-t-elle déjà reçu le DM dans les dernières 24 heures ?"},{"t":"msg","text":"Sinon : « Bonjour [nom], merci d'avoir regardé ! Voici ce que tu as demandé : [lien]. »"},{"t":"delay","v":10},{"t":"msg","text":"Petit suivi : « Le lien a bien fonctionné ? Dis-moi si tu as besoin d'autre chose. »"},{"t":"tag","text":"Tag : lead-reel (ignorer si doublon)"}],"pt":[{"t":"trigger","text":"Novo comentário em um reel com a palavra-chave da campanha"},{"t":"cond","text":"Essa pessoa já recebeu a DM nas últimas 24 horas?"},{"t":"msg","text":"Se não: «Olá [nome], obrigado por assistir! Aqui está o que você pediu: [link].»"},{"t":"delay","v":10},{"t":"msg","text":"Follow-up rápido: «O link abriu direitinho? Me avisa se precisar de mais alguma coisa.»"},{"t":"tag","text":"Tag: lead-reel (pular se duplicado)"}]},"story-mention-thank-you":{"en":[{"t":"trigger","text":"Customer mentions the brand in their story"},{"t":"msg","text":"Thank you so much for sharing us, [name]! It really made our day."},{"t":"delay","v":5},{"t":"msg","text":"As a thank-you, here is your personal code: [REFERRAL CODE] for [offer] on your next order. Share it with a friend too."},{"t":"tag","text":"Tag: story-advocate"}],"ar":[{"t":"trigger","text":"عميل عمل منشن للبراند في الستوري"},{"t":"msg","text":"شكرًا جدًا إنك شاركتنا يا [الاسم]! فرّحتنا فعلًا."},{"t":"delay","v":5},{"t":"msg","text":"هدية شكر منّنا، كودك الخاص: [كود الإحالة] لـ [العرض] على طلبك الجاي. شاركه مع صاحبك كمان."},{"t":"tag","text":"وسم: سفير-ستوري"}],"de":[{"t":"trigger","text":"Kunde erwähnt die Marke in seiner Story"},{"t":"msg","text":"Danke, dass du uns geteilt hast, [Name]! Das hat uns wirklich den Tag versüßt."},{"t":"delay","v":5},{"t":"msg","text":"Als Dankeschön hier dein persönlicher Code: [EMPFEHLUNGSCODE] für [Angebot] bei deiner nächsten Bestellung. Teile ihn gern auch mit einer Freundin oder einem Freund."},{"t":"tag","text":"Tag: story-fan"}],"es":[{"t":"trigger","text":"El cliente menciona la marca en su story"},{"t":"msg","text":"¡Muchas gracias por compartirnos, [nombre]! De verdad nos alegraste el día."},{"t":"delay","v":5},{"t":"msg","text":"Como agradecimiento, aquí tienes tu código personal: [CÓDIGO DE REFERIDO] para [oferta] en tu próximo pedido. Compártelo también con un amigo."},{"t":"tag","text":"Etiqueta: fan-story"}],"fr":[{"t":"trigger","text":"Le client mentionne la marque dans sa story"},{"t":"msg","text":"Merci beaucoup de nous avoir partagés, [nom] ! Ça nous a vraiment fait plaisir."},{"t":"delay","v":5},{"t":"msg","text":"Pour te remercier, voici ton code personnel : [CODE DE PARRAINAGE] pour [offre] sur ta prochaine commande. Partage-le aussi avec un ami."},{"t":"tag","text":"Tag : fan-story"}],"pt":[{"t":"trigger","text":"Cliente menciona a marca no story"},{"t":"msg","text":"Muito obrigado por compartilhar a gente, [nome]! Isso realmente fez nosso dia."},{"t":"delay","v":5},{"t":"msg","text":"Como agradecimento, aqui está seu código pessoal: [CÓDIGO DE INDICAÇÃO] para [oferta] no seu próximo pedido. Compartilha com um amigo também."},{"t":"tag","text":"Tag: fã-story"}]},"dm-price-answer":{"en":[{"t":"trigger","text":"DM contains \"how much\", \"price\" or \"cost\""},{"t":"msg","text":"Hi [name]! [product] is [price] right now. [In stock / only a few left]. Delivery to [city]: [delivery fee]."},{"t":"msg","text":"Want me to reserve it for you? Send your name, address and phone, or tap here to check out: [checkout link]."}],"ar":[{"t":"trigger","text":"رسالة فيها \"بكام\" أو \"السعر\" أو \"التكلفة\""},{"t":"msg","text":"أهلاً [الاسم]! [المنتج] سعره دلوقتي [السعر]. [متوفر / باقي قطع قليلة]. التوصيل لـ [المدينة]: [رسوم التوصيل]."},{"t":"msg","text":"تحب أحجزهولك؟ ابعتلي الاسم والعنوان والتليفون، أو كمّل من هنا: [لينك الدفع]."}],"de":[{"t":"trigger","text":"DM enthält „was kostet“, „Preis“ oder „Kosten“"},{"t":"msg","text":"Hallo [Name]! [Produkt] kostet gerade [Preis]. [Auf Lager / nur noch wenige]. Lieferung nach [Stadt]: [Liefergebühr]."},{"t":"msg","text":"Soll ich es für dich reservieren? Schick mir Name, Adresse und Telefonnummer, oder tippe hier zum Bezahlen: [Checkout-Link]."}],"es":[{"t":"trigger","text":"DM contiene «cuánto cuesta», «precio» o «coste»"},{"t":"msg","text":"¡Hola [nombre]! [producto] está a [precio] ahora mismo. [En stock / quedan pocos]. Envío a [ciudad]: [coste de envío]."},{"t":"msg","text":"¿Quieres que te lo reserve? Envíame nombre, dirección y teléfono, o toca aquí para pagar: [enlace de pago]."}],"fr":[{"t":"trigger","text":"DM contient « combien », « prix » ou « coût »"},{"t":"msg","text":"Bonjour [nom] ! [produit] est à [prix] en ce moment. [En stock / il n'en reste que quelques-uns]. Livraison à [ville] : [frais de livraison]."},{"t":"msg","text":"Tu veux que je te le réserve ? Envoie-moi nom, adresse et téléphone, ou touche ici pour payer : [lien de paiement]."}],"pt":[{"t":"trigger","text":"DM contém «quanto custa», «preço» ou «valor»"},{"t":"msg","text":"Olá [nome]! [produto] está por [preço] agora. [Em estoque / restam poucos]. Entrega em [cidade]: [taxa de entrega]."},{"t":"msg","text":"Quer que eu reserve pra você? Me manda nome, endereço e telefone, ou toca aqui pra pagar: [link de pagamento]."}]},"follower-only-drop":{"en":[{"t":"trigger","text":"DM contains the keyword \"DROP\""},{"t":"cond","text":"Does this person follow the account?"},{"t":"msg","text":"Yes: \"You are on the list, [name]! Early access opens [date and time]. Here is your private link: [link].\""},{"t":"msg","text":"No: \"Follow us at [@account] first, then send DROP again and I will add you.\""},{"t":"tag","text":"Tag: early-access"}],"ar":[{"t":"trigger","text":"رسالة فيها كلمة \"DROP\""},{"t":"cond","text":"هل الشخص ده متابع للحساب؟"},{"t":"msg","text":"لو أيوه: \"اسمك في القايمة يا [الاسم]! الدخول المبكر بيفتح [التاريخ والوقت]. ده لينكك الخاص: [اللينك].\""},{"t":"msg","text":"لو لأ: \"تابعنا الأول على [@الحساب] وبعدين ابعت DROP تاني وأضيفك.\""},{"t":"tag","text":"وسم: دخول-مبكر"}],"de":[{"t":"trigger","text":"DM enthält das Schlüsselwort „DROP“"},{"t":"cond","text":"Folgt diese Person dem Konto?"},{"t":"msg","text":"Ja: „Du bist dabei, [Name]! Der frühe Zugang öffnet [Datum und Uhrzeit]. Hier ist dein privater Link: [Link].“"},{"t":"msg","text":"Nein: „Folge uns erst unter [@Konto], dann schick DROP nochmal und ich nehme dich auf.“"},{"t":"tag","text":"Tag: early-access"}],"es":[{"t":"trigger","text":"DM contiene la palabra clave «DROP»"},{"t":"cond","text":"¿Esta persona sigue la cuenta?"},{"t":"msg","text":"Sí: «¡Ya estás en la lista, [nombre]! El acceso anticipado abre [fecha y hora]. Aquí está tu enlace privado: [enlace].»"},{"t":"msg","text":"No: «Síguenos primero en [@cuenta], luego envía DROP otra vez y te agrego.»"},{"t":"tag","text":"Etiqueta: acceso-anticipado"}],"fr":[{"t":"trigger","text":"DM contient le mot-clé « DROP »"},{"t":"cond","text":"Cette personne suit-elle le compte ?"},{"t":"msg","text":"Oui : « Tu es sur la liste, [nom] ! L'accès anticipé ouvre [date et heure]. Voici ton lien privé : [lien]. »"},{"t":"msg","text":"Non : « Abonne-toi d'abord à [@compte], puis renvoie DROP et je t'ajoute. »"},{"t":"tag","text":"Tag : accès-anticipé"}],"pt":[{"t":"trigger","text":"DM contém a palavra-chave «DROP»"},{"t":"cond","text":"Essa pessoa segue a conta?"},{"t":"msg","text":"Sim: «Você está na lista, [nome]! O acesso antecipado abre [data e hora]. Aqui está seu link privado: [link].»"},{"t":"msg","text":"Não: «Segue a gente primeiro em [@conta], depois manda DROP de novo que eu te adiciono.»"},{"t":"tag","text":"Tag: acesso-antecipado"}]},"abandoned-dm-recovery":{"en":[{"t":"trigger","text":"Customer asked about a product and went quiet for 2 hours"},{"t":"msg","text":"Hi [name], still thinking about [product]? I can answer any question about size, delivery or payment."},{"t":"delay","v":1440},{"t":"msg","text":"Last check-in: [product] is still available. Reply \"YES\" and I will hold it for you. Reply \"STOP\" to opt out."}],"ar":[{"t":"trigger","text":"عميل سأل عن منتج وسكت ساعتين"},{"t":"msg","text":"أهلاً [الاسم]، لسه بتفكر في [المنتج]؟ أقدر أجاوب أي سؤال عن المقاس أو التوصيل أو الدفع."},{"t":"delay","v":1440},{"t":"msg","text":"آخر رسالة: [المنتج] لسه متاح. اكتب \"أيوه\" وأحجزهولك. اكتب \"إيقاف\" لو مش عايز رسايل."}],"de":[{"t":"trigger","text":"Kunde hat nach einem Produkt gefragt und ist seit 2 Stunden still"},{"t":"msg","text":"Hallo [Name], überlegst du noch wegen [Produkt]? Ich beantworte gern jede Frage zu Größe, Lieferung oder Zahlung."},{"t":"delay","v":1440},{"t":"msg","text":"Letzte Nachfrage: [Produkt] ist noch verfügbar. Antworte „JA“ und ich lege es für dich zurück. Antworte „STOPP“ zum Abmelden."}],"es":[{"t":"trigger","text":"El cliente preguntó por un producto y lleva 2 horas sin responder"},{"t":"msg","text":"Hola [nombre], ¿sigues pensándote lo de [producto]? Puedo responder cualquier duda sobre talla, envío o pago."},{"t":"delay","v":1440},{"t":"msg","text":"Último aviso: [producto] sigue disponible. Responde «SÍ» y te lo aparto. Responde «STOP» para darte de baja."}],"fr":[{"t":"trigger","text":"Le client a posé une question sur un produit puis n'a plus répondu depuis 2 heures"},{"t":"msg","text":"Bonjour [nom], tu réfléchis encore à propos de [produit] ? Je peux répondre à toute question sur la taille, la livraison ou le paiement."},{"t":"delay","v":1440},{"t":"msg","text":"Dernière relance : [produit] est toujours disponible. Réponds « OUI » et je te le mets de côté. Réponds « STOP » pour te désinscrire."}],"pt":[{"t":"trigger","text":"Cliente perguntou sobre um produto e sumiu há 2 horas"},{"t":"msg","text":"Olá [nome], ainda tá pensando sobre [produto]? Posso responder qualquer dúvida sobre tamanho, entrega ou pagamento."},{"t":"delay","v":1440},{"t":"msg","text":"Último contato: [produto] ainda está disponível. Responde «SIM» que eu separo pra você. Responde «PARAR» para sair."}]},"ugc-rights-request":{"en":[{"t":"trigger","text":"Customer tags the brand in a post with the product"},{"t":"msg","text":"Love this photo, [name]! May we share it on our page and website, with credit to [@handle]? Reply \"YES\" to allow."},{"t":"cond","text":"Did they reply \"YES\"?"},{"t":"tag","text":"Save the post link, the handle and the date of consent. Tag: ugc-approved"}],"ar":[{"t":"trigger","text":"عميل عمل تاج للبراند في بوست فيه المنتج"},{"t":"msg","text":"الصورة تجنن يا [الاسم]! نقدر ننشرها على صفحتنا وموقعنا مع ذكر [@الحساب]؟ اكتب \"أيوه\" للموافقة."},{"t":"cond","text":"هل ردّ بـ \"أيوه\"؟"},{"t":"tag","text":"احفظ لينك البوست والحساب وتاريخ الموافقة. وسم: محتوى-موافق-عليه"}],"de":[{"t":"trigger","text":"Kunde markiert die Marke in einem Beitrag mit dem Produkt"},{"t":"msg","text":"Tolles Foto, [Name]! Dürfen wir es auf unserer Seite und Website teilen, mit Nennung von [@Handle]? Antworte „JA“ zur Zustimmung."},{"t":"cond","text":"Haben sie mit „JA“ geantwortet?"},{"t":"tag","text":"Beitragslink, Handle und Datum der Zustimmung speichern. Tag: ugc-genehmigt"}],"es":[{"t":"trigger","text":"El cliente etiqueta la marca en una publicación con el producto"},{"t":"msg","text":"¡Nos encanta esta foto, [nombre]! ¿Podemos compartirla en nuestra página y web, con crédito a [@usuario]? Responde «SÍ» para autorizar."},{"t":"cond","text":"¿Respondieron «SÍ»?"},{"t":"tag","text":"Guarda el enlace de la publicación, el usuario y la fecha del consentimiento. Etiqueta: ugc-aprobado"}],"fr":[{"t":"trigger","text":"Le client identifie la marque dans une publication avec le produit"},{"t":"msg","text":"On adore cette photo, [nom] ! Peut-on la partager sur notre page et notre site, avec crédit à [@pseudo] ? Réponds « OUI » pour autoriser."},{"t":"cond","text":"Ont-ils répondu « OUI » ?"},{"t":"tag","text":"Enregistrer le lien de la publication, le pseudo et la date du consentement. Tag : ugc-approuvé"}],"pt":[{"t":"trigger","text":"Cliente marca a marca em um post com o produto"},{"t":"msg","text":"Adoramos essa foto, [nome]! Podemos compartilhar na nossa página e no site, com crédito para [@perfil]? Responde «SIM» para autorizar."},{"t":"cond","text":"Responderam «SIM»?"},{"t":"tag","text":"Salvar o link do post, o perfil e a data do consentimento. Tag: ugc-aprovado"}]},"influencer-collab-intake":{"en":[{"t":"trigger","text":"DM contains \"collab\" or \"partnership\""},{"t":"msg","text":"Hi [name], thanks for reaching out! A few quick questions. What is your Instagram handle and your follower count?"},{"t":"msg","text":"What is your niche, and what is your rate for one post or reel?"},{"t":"cond","text":"Does the creator match our rules (niche, minimum followers, rate within budget)?"},{"t":"msg","text":"If yes: \"Great fit! Pick a time for a 15-minute call: [calendar link].\" If not: \"Thank you, we will keep your details for future campaigns.\""},{"t":"tag","text":"Tag: creator-lead"}],"ar":[{"t":"trigger","text":"رسالة فيها \"تعاون\" أو \"شراكة\""},{"t":"msg","text":"أهلاً [الاسم]، شكرًا لتواصلك! كام سؤال سريع. إيه حسابك وعدد متابعينك؟"},{"t":"msg","text":"إيه مجالك، وسعرك لبوست أو ريل واحد؟"},{"t":"cond","text":"هل الصانع مناسب لمعاييرنا (المجال، الحد الأدنى للمتابعين، السعر في الميزانية)؟"},{"t":"msg","text":"لو مناسب: \"مناسب جدًا! اختار ميعاد لمكالمة 15 دقيقة: [لينك التقويم].\" لو لأ: \"شكرًا، هنحتفظ ببياناتك لحملات جاية.\""},{"t":"tag","text":"وسم: صانع-محتوى"}],"de":[{"t":"trigger","text":"DM enthält „Collab“ oder „Kooperation“"},{"t":"msg","text":"Hallo [Name], danke für deine Nachricht! Ein paar kurze Fragen. Wie lautet dein Instagram-Handle und deine Followerzahl?"},{"t":"msg","text":"Was ist deine Nische, und was ist dein Preis für einen Beitrag oder ein Reel?"},{"t":"cond","text":"Passt der Creator zu unseren Regeln (Nische, Mindest-Followerzahl, Preis im Budget)?"},{"t":"msg","text":"Falls ja: „Passt super! Such dir einen Termin für ein 15-minütiges Gespräch: [Kalenderlink].“ Falls nicht: „Danke, wir behalten deine Daten für künftige Kampagnen.“"},{"t":"tag","text":"Tag: creator-lead"}],"es":[{"t":"trigger","text":"DM contiene «colaboración» o «partnership»"},{"t":"msg","text":"Hola [nombre], ¡gracias por escribirnos! Unas preguntas rápidas. ¿Cuál es tu usuario de Instagram y tu número de seguidores?"},{"t":"msg","text":"¿Cuál es tu nicho y tu tarifa por una publicación o reel?"},{"t":"cond","text":"¿El creador encaja con nuestras reglas (nicho, mínimo de seguidores, tarifa dentro del presupuesto)?"},{"t":"msg","text":"Si sí: «¡Perfecto! Elige hora para una llamada de 15 minutos: [enlace de calendario].» Si no: «Gracias, guardaremos tus datos para futuras campañas.»"},{"t":"tag","text":"Etiqueta: lead-creador"}],"fr":[{"t":"trigger","text":"DM contient « collab » ou « partenariat »"},{"t":"msg","text":"Bonjour [nom], merci pour ton message ! Quelques questions rapides. Quel est ton pseudo Instagram et ton nombre d'abonnés ?"},{"t":"msg","text":"Quelle est ta niche, et quel est ton tarif pour une publication ou un reel ?"},{"t":"cond","text":"Le créateur correspond-il à nos règles (niche, abonnés minimum, tarif dans le budget) ?"},{"t":"msg","text":"Si oui : « Parfait ! Choisis un créneau pour un appel de 15 minutes : [lien du calendrier]. » Sinon : « Merci, nous gardons tes coordonnées pour de futures campagnes. »"},{"t":"tag","text":"Tag : lead-créateur"}],"pt":[{"t":"trigger","text":"DM contém «collab» ou «parceria»"},{"t":"msg","text":"Olá [nome], obrigado por escrever! Algumas perguntas rápidas. Qual é seu perfil do Instagram e seu número de seguidores?"},{"t":"msg","text":"Qual é seu nicho e seu preço por um post ou reel?"},{"t":"cond","text":"O criador se encaixa nas nossas regras (nicho, mínimo de seguidores, preço dentro do orçamento)?"},{"t":"msg","text":"Se sim: «Ótimo! Escolhe um horário para uma chamada de 15 minutos: [link do calendário].» Se não: «Obrigado, vamos guardar seus dados para futuras campanhas.»"},{"t":"tag","text":"Tag: lead-criador"}]},"whatsapp-order-confirmation":{"en":[{"t":"trigger","text":"New cash-on-delivery order placed"},{"t":"msg","text":"Hi [name], your order #[order] ([items], total [amount]) is ready to ship. Reply ✅ to confirm or ❌ to cancel."},{"t":"cond","text":"Reply: ✅ or ❌, or no reply after 12 hours?"},{"t":"tag","text":"✅ Tag \"confirmed\" and release for dispatch. ❌ Tag \"cancelled\". No reply: send one reminder, then hand to an agent."}],"ar":[{"t":"trigger","text":"طلب جديد بالدفع عند الاستلام"},{"t":"msg","text":"أهلاً [الاسم]، طلبك رقم [رقم الطلب] ([المنتجات]، الإجمالي [المبلغ]) جاهز للشحن. ردّ ✅ للتأكيد أو ❌ للإلغاء."},{"t":"cond","text":"الرد: ✅ ولا ❌ ولا مفيش رد بعد 12 ساعة؟"},{"t":"tag","text":"✅ وسم \"مؤكد\" وسلّم للشحن. ❌ وسم \"ملغي\". مفيش رد: ابعت تذكير واحد وبعدين حوّل لموظف."}],"de":[{"t":"trigger","text":"Neue Nachnahme-Bestellung eingegangen"},{"t":"msg","text":"Hallo [Name], deine Bestellung #[Bestellnummer] ([Artikel], Summe [Betrag]) ist versandbereit. Antworte ✅ zum Bestätigen oder ❌ zum Stornieren."},{"t":"cond","text":"Antwort: ✅ oder ❌, oder keine Antwort nach 12 Stunden?"},{"t":"tag","text":"✅ Tag „bestätigt“ und zum Versand freigeben. ❌ Tag „storniert“. Keine Antwort: eine Erinnerung schicken, dann an einen Mitarbeiter übergeben."}],"es":[{"t":"trigger","text":"Nuevo pedido contra reembolso realizado"},{"t":"msg","text":"Hola [nombre], tu pedido #[pedido] ([artículos], total [importe]) está listo para enviar. Responde ✅ para confirmar o ❌ para cancelar."},{"t":"cond","text":"Respuesta: ✅ o ❌, ¿o sin respuesta tras 12 horas?"},{"t":"tag","text":"✅ Etiqueta «confirmado» y liberar para envío. ❌ Etiqueta «cancelado». Sin respuesta: enviar un recordatorio y pasar a un agente."}],"fr":[{"t":"trigger","text":"Nouvelle commande en contre-remboursement passée"},{"t":"msg","text":"Bonjour [nom], ta commande n°[commande] ([articles], total [montant]) est prête à être expédiée. Réponds ✅ pour confirmer ou ❌ pour annuler."},{"t":"cond","text":"Réponse : ✅ ou ❌, ou pas de réponse après 12 heures ?"},{"t":"tag","text":"✅ Tag « confirmée » et libérer pour l'expédition. ❌ Tag « annulée ». Pas de réponse : envoyer un rappel, puis transmettre à un agent."}],"pt":[{"t":"trigger","text":"Novo pedido em pagamento na entrega realizado"},{"t":"msg","text":"Olá [nome], seu pedido #[pedido] ([itens], total [valor]) está pronto para envio. Responde ✅ para confirmar ou ❌ para cancelar."},{"t":"cond","text":"Resposta: ✅ ou ❌, ou sem resposta após 12 horas?"},{"t":"tag","text":"✅ Tag «confirmado» e liberar para despacho. ❌ Tag «cancelado». Sem resposta: enviar um lembrete e passar para um atendente."}]},"cod-failed-delivery-rescue":{"en":[{"t":"trigger","text":"Courier marks the delivery as failed"},{"t":"msg","text":"Hi [name], the courier could not reach you today for order #[order]. When is a good time tomorrow?"},{"t":"delay","v":120},{"t":"cond","text":"Did the customer reply with a time?"},{"t":"msg","text":"If yes: \"Done, we rescheduled for [time]. Please keep your phone on and have [amount] ready.\" If no: \"Reply with a time, or CALL for a phone call.\""},{"t":"tag","text":"Tag: delivery-rescheduled or needs-agent"}],"ar":[{"t":"trigger","text":"شركة الشحن سجّلت إن التسليم فشل"},{"t":"msg","text":"أهلاً [الاسم]، شركة الشحن معرفتش توصلك النهارده بخصوص طلب رقم [رقم الطلب]. إيه أنسب ميعاد بكرة؟"},{"t":"delay","v":120},{"t":"cond","text":"هل العميل ردّ بميعاد؟"},{"t":"msg","text":"لو أيوه: \"تمام، حددنا [الميعاد]. من فضلك خلي تليفونك مفتوح وجهّز [المبلغ].\" لو لأ: \"ابعت ميعاد أو اكتب اتصال لمكالمة.\""},{"t":"tag","text":"وسم: توصيل-معاد-جدولته أو يحتاج-موظف"}],"de":[{"t":"trigger","text":"Kurier markiert die Zustellung als gescheitert"},{"t":"msg","text":"Hallo [Name], der Kurier konnte dich heute für Bestellung #[Bestellnummer] nicht erreichen. Wann passt es morgen?"},{"t":"delay","v":120},{"t":"cond","text":"Hat der Kunde mit einer Uhrzeit geantwortet?"},{"t":"msg","text":"Falls ja: „Erledigt, wir haben auf [Uhrzeit] umgeplant. Bitte lass dein Telefon an und halte [Betrag] bereit.“ Falls nein: „Antworte mit einer Uhrzeit, oder schick ANRUF für einen Rückruf.“"},{"t":"tag","text":"Tag: lieferung-umgeplant oder braucht-mitarbeiter"}],"es":[{"t":"trigger","text":"El courier marca la entrega como fallida"},{"t":"msg","text":"Hola [nombre], el courier no pudo encontrarte hoy para el pedido #[pedido]. ¿A qué hora te va bien mañana?"},{"t":"delay","v":120},{"t":"cond","text":"¿El cliente respondió con una hora?"},{"t":"msg","text":"Si sí: «Listo, reprogramamos para [hora]. Por favor ten el teléfono encendido y prepara [importe].» Si no: «Responde con una hora, o envía LLAMADA para que te llamemos.»"},{"t":"tag","text":"Etiqueta: entrega-reprogramada o necesita-agente"}],"fr":[{"t":"trigger","text":"Le transporteur marque la livraison comme échouée"},{"t":"msg","text":"Bonjour [nom], le livreur n'a pas pu te joindre aujourd'hui pour la commande n°[commande]. À quelle heure ça t'irait demain ?"},{"t":"delay","v":120},{"t":"cond","text":"Le client a-t-il répondu avec un horaire ?"},{"t":"msg","text":"Si oui : « C'est fait, nous avons replanifié à [horaire]. Garde ton téléphone allumé et prépare [montant]. » Si non : « Réponds avec un horaire, ou envoie APPEL pour un appel téléphonique. »"},{"t":"tag","text":"Tag : livraison-replanifiée ou besoin-agent"}],"pt":[{"t":"trigger","text":"Transportadora marca a entrega como falha"},{"t":"msg","text":"Olá [nome], o entregador não conseguiu te encontrar hoje para o pedido #[pedido]. Qual horário fica bom amanhã?"},{"t":"delay","v":120},{"t":"cond","text":"O cliente respondeu com um horário?"},{"t":"msg","text":"Se sim: «Feito, reagendamos para [horário]. Deixa o telefone ligado e separa [valor].» Se não: «Responde com um horário, ou manda LIGAR para receber uma ligação.»"},{"t":"tag","text":"Tag: entrega-reagendada ou precisa-atendente"}]},"whatsapp-catalogue-browse":{"en":[{"t":"trigger","text":"Customer sends \"catalogue\" or \"menu\""},{"t":"msg","text":"Hi [name]! Here is our catalogue: [catalogue link]. What are you shopping for today?"},{"t":"cond","text":"Is the question about size, color or availability?"},{"t":"msg","text":"Sizing: \"Tell me your height and weight (or usual size) and I will suggest the best fit from our size chart: [size chart link].\""},{"t":"msg","text":"\"Here is the exact item: [variant link]. Want me to add it to an order?\""}],"ar":[{"t":"trigger","text":"العميل يبعت \"كتالوج\" أو \"المنيو\""},{"t":"msg","text":"أهلاً [الاسم]! ده الكتالوج بتاعنا: [لينك الكتالوج]. بتدوّر على إيه النهارده؟"},{"t":"cond","text":"هل السؤال عن المقاس أو اللون أو التوفر؟"},{"t":"msg","text":"المقاس: \"قولي طولك ووزنك (أو مقاسك المعتاد) وأرشحلك الأنسب من جدول المقاسات: [لينك الجدول].\""},{"t":"msg","text":"\"ده المنتج بالظبط: [لينك الخيار]. تحب أضيفه لطلب؟\""}],"de":[{"t":"trigger","text":"Kunde schickt „Katalog“ oder „Menü“"},{"t":"msg","text":"Hallo [Name]! Hier ist unser Katalog: [Kataloglink]. Wonach suchst du heute?"},{"t":"cond","text":"Geht die Frage um Größe, Farbe oder Verfügbarkeit?"},{"t":"msg","text":"Größen: „Sag mir deine Größe und dein Gewicht (oder deine übliche Größe), dann schlage ich die beste Passform aus unserer Größentabelle vor: [Größentabelle-Link].“"},{"t":"msg","text":"„Hier ist der genaue Artikel: [Variantenlink]. Soll ich ihn einer Bestellung hinzufügen?“"}],"es":[{"t":"trigger","text":"El cliente envía «catálogo» o «menú»"},{"t":"msg","text":"¡Hola [nombre]! Aquí está nuestro catálogo: [enlace del catálogo]. ¿Qué estás buscando hoy?"},{"t":"cond","text":"¿La pregunta es sobre talla, color o disponibilidad?"},{"t":"msg","text":"Tallas: «Dime tu altura y peso (o tu talla habitual) y te sugiero el mejor ajuste de nuestra guía de tallas: [enlace de guía de tallas].»"},{"t":"msg","text":"«Aquí está el artículo exacto: [enlace de variante]. ¿Quieres que lo añada a un pedido?»"}],"fr":[{"t":"trigger","text":"Le client envoie « catalogue » ou « menu »"},{"t":"msg","text":"Bonjour [nom] ! Voici notre catalogue : [lien du catalogue]. Qu'est-ce que tu cherches aujourd'hui ?"},{"t":"cond","text":"La question porte-t-elle sur la taille, la couleur ou la disponibilité ?"},{"t":"msg","text":"Tailles : « Donne-moi ta taille et ton poids (ou ta taille habituelle) et je te suggère le meilleur ajustement dans notre guide des tailles : [lien du guide des tailles]. »"},{"t":"msg","text":"« Voici l'article exact : [lien de la variante]. Tu veux que je l'ajoute à une commande ? »"}],"pt":[{"t":"trigger","text":"Cliente envia «catálogo» ou «cardápio»"},{"t":"msg","text":"Olá [nome]! Aqui está nosso catálogo: [link do catálogo]. O que você tá procurando hoje?"},{"t":"cond","text":"A dúvida é sobre tamanho, cor ou disponibilidade?"},{"t":"msg","text":"Tamanhos: «Me diz sua altura e peso (ou seu tamanho habitual) que eu sugiro o melhor ajuste da nossa tabela de medidas: [link da tabela].»"},{"t":"msg","text":"«Aqui está o item exato: [link da variante]. Quer que eu adicione em um pedido?»"}]},"back-in-stock-alert":{"en":[{"t":"trigger","text":"Customer taps \"Notify me\" on a sold-out product"},{"t":"msg","text":"Hi [name], we will message you the moment [product] is back. Reply \"STOP\" at any time to cancel."},{"t":"tag","text":"Tag: waiting-[product]"},{"t":"cond","text":"Is [product] back in stock?"},{"t":"msg","text":"\"Good news [name], [product] is back! Quantities are limited: [link].\""}],"ar":[{"t":"trigger","text":"عميل ضغط \"بلغني\" على منتج خلصان"},{"t":"msg","text":"أهلاً [الاسم]، هنبلغك أول ما [المنتج] يرجع. اكتب \"إيقاف\" في أي وقت للإلغاء."},{"t":"tag","text":"وسم: منتظر-[المنتج]"},{"t":"cond","text":"هل [المنتج] رجع المخزون؟"},{"t":"msg","text":"\"خبر حلو يا [الاسم]، [المنتج] رجع! الكميات محدودة: [اللينك].\""}],"de":[{"t":"trigger","text":"Kunde tippt bei einem ausverkauften Produkt auf „Benachrichtigen“"},{"t":"msg","text":"Hallo [Name], wir schreiben dir, sobald [Produkt] wieder da ist. Antworte jederzeit „STOPP“ zum Abbestellen."},{"t":"tag","text":"Tag: wartet-[Produkt]"},{"t":"cond","text":"Ist [Produkt] wieder auf Lager?"},{"t":"msg","text":"„Gute Nachrichten, [Name]: [Produkt] ist wieder da! Die Stückzahl ist begrenzt: [Link].“"}],"es":[{"t":"trigger","text":"El cliente toca «Avísame» en un producto agotado"},{"t":"msg","text":"Hola [nombre], te escribiremos en cuanto [producto] vuelva. Responde «STOP» en cualquier momento para cancelar."},{"t":"tag","text":"Etiqueta: esperando-[producto]"},{"t":"cond","text":"¿[producto] volvió a estar en stock?"},{"t":"msg","text":"«Buenas noticias, [nombre]: ¡[producto] volvió! Las unidades son limitadas: [enlace].»"}],"fr":[{"t":"trigger","text":"Le client touche « Me prévenir » sur un produit épuisé"},{"t":"msg","text":"Bonjour [nom], on t'écrira dès que [produit] sera de retour. Réponds « STOP » à tout moment pour annuler."},{"t":"tag","text":"Tag : attente-[produit]"},{"t":"cond","text":"[produit] est-il de retour en stock ?"},{"t":"msg","text":"« Bonne nouvelle [nom], [produit] est de retour ! Les quantités sont limitées : [lien]. »"}],"pt":[{"t":"trigger","text":"Cliente toca em «Me avise» num produto esgotado"},{"t":"msg","text":"Olá [nome], a gente te avisa assim que [produto] voltar. Responde «PARAR» a qualquer momento para cancelar."},{"t":"tag","text":"Tag: aguardando-[produto]"},{"t":"cond","text":"[produto] voltou ao estoque?"},{"t":"msg","text":"«Boa notícia, [nome]: [produto] voltou! As unidades são limitadas: [link].»"}]},"ramadan-offer-broadcast":{"en":[{"t":"trigger","text":"Scheduled broadcast to the \"ramadan-offer\" segment"},{"t":"cond","text":"Is it within quiet hours (e.g. after 10 PM or during prayer times)? If yes, wait."},{"t":"msg","text":"Ramadan Kareem [name]! Our Ramadan offer: [offer] until [date]. Shop here: [link]. Reply \"STOP\" to unsubscribe."},{"t":"tag","text":"Anyone who replies \"STOP\": tag opted-out and exclude from future broadcasts"}],"ar":[{"t":"trigger","text":"بث مجدول للشريحة \"عرض-رمضان\""},{"t":"cond","text":"هل الوقت ضمن ساعات الهدوء (مثلًا بعد 10 مساءً أو وقت الصلاة)؟ لو أيوه استنى."},{"t":"msg","text":"رمضان كريم يا [الاسم]! عرض رمضان: [العرض] لحد [التاريخ]. اطلب من هنا: [اللينك]. اكتب \"إيقاف\" لإلغاء الاشتراك."},{"t":"tag","text":"أي حد يرد \"إيقاف\": وسم ملغي-الاشتراك واستبعده من البث الجاي"}],"de":[{"t":"trigger","text":"Geplanter Broadcast an das Segment „ramadan-angebot“"},{"t":"cond","text":"Ist gerade Ruhezeit (z. B. nach 22 Uhr oder zu Gebetszeiten)? Falls ja, warten."},{"t":"msg","text":"Ramadan Kareem, [Name]! Unser Ramadan-Angebot: [Angebot] bis [Datum]. Hier shoppen: [Link]. Antworte „STOPP“ zum Abbestellen."},{"t":"tag","text":"Alle, die „STOPP“ antworten: Tag abgemeldet und von künftigen Broadcasts ausschließen"}],"es":[{"t":"trigger","text":"Difusión programada al segmento «oferta-ramadán»"},{"t":"cond","text":"¿Está en horario de silencio (p. ej. después de las 22 h o en horas de oración)? Si es así, esperar."},{"t":"msg","text":"¡Ramadán Karim, [nombre]! Nuestra oferta de Ramadán: [oferta] hasta [fecha]. Compra aquí: [enlace]. Responde «STOP» para darte de baja."},{"t":"tag","text":"Quien responda «STOP»: etiqueta dado-de-baja y excluir de futuras difusiones"}],"fr":[{"t":"trigger","text":"Diffusion programmée au segment « offre-ramadan »"},{"t":"cond","text":"Sommes-nous dans les heures silencieuses (p. ex. après 22 h ou pendant les prières) ? Si oui, attendre."},{"t":"msg","text":"Ramadan Karim [nom] ! Notre offre du Ramadan : [offre] jusqu'au [date]. Achète ici : [lien]. Réponds « STOP » pour te désabonner."},{"t":"tag","text":"Quiconque répond « STOP » : tag désabonné et exclure des futures diffusions"}],"pt":[{"t":"trigger","text":"Transmissão programada para o segmento «oferta-ramadã»"},{"t":"cond","text":"Está no horário de silêncio (ex.: depois das 22h ou nos horários de oração)? Se sim, aguardar."},{"t":"msg","text":"Ramadan Kareem, [nome]! Nossa oferta de Ramadã: [oferta] até [data]. Compre aqui: [link]. Responde «PARAR» para cancelar."},{"t":"tag","text":"Quem responder «PARAR»: tag descadastrado e excluir de futuras transmissões"}]},"delivery-tracking-updates":{"en":[{"t":"trigger","text":"Order status changes to shipped or out for delivery"},{"t":"msg","text":"Hi [name], order #[order] is on its way with [courier]. Expected delivery: [ETA]. Track it: [tracking link]."},{"t":"msg","text":"Not home? Reply with a new time or address and we will pass it to the courier."}],"ar":[{"t":"trigger","text":"حالة الطلب اتغيرت لـ تم الشحن أو في الطريق"},{"t":"msg","text":"أهلاً [الاسم]، طلب رقم [رقم الطلب] في الطريق مع [شركة الشحن]. التسليم المتوقع: [الموعد]. تابعه: [لينك التتبع]."},{"t":"msg","text":"مش هتكون موجود؟ ابعت ميعاد أو عنوان جديد وهنبلغ شركة الشحن."}],"de":[{"t":"trigger","text":"Bestellstatus wechselt zu versandt oder in Zustellung"},{"t":"msg","text":"Hallo [Name], Bestellung #[Bestellnummer] ist mit [Kurier] unterwegs. Voraussichtliche Zustellung: [ETA]. Verfolgen: [Tracking-Link]."},{"t":"msg","text":"Nicht zu Hause? Antworte mit einer neuen Uhrzeit oder Adresse, wir geben es an den Kurier weiter."}],"es":[{"t":"trigger","text":"El estado del pedido cambia a enviado o en reparto"},{"t":"msg","text":"Hola [nombre], el pedido #[pedido] va en camino con [courier]. Entrega estimada: [ETA]. Síguelo: [enlace de seguimiento]."},{"t":"msg","text":"¿No estás en casa? Responde con una nueva hora o dirección y se lo pasamos al courier."}],"fr":[{"t":"trigger","text":"Le statut de la commande passe à expédiée ou en cours de livraison"},{"t":"msg","text":"Bonjour [nom], la commande n°[commande] est en route avec [transporteur]. Livraison prévue : [ETA]. Suivi : [lien de suivi]."},{"t":"msg","text":"Pas chez toi ? Réponds avec un nouvel horaire ou une nouvelle adresse et on le transmet au livreur."}],"pt":[{"t":"trigger","text":"Status do pedido muda para enviado ou saiu para entrega"},{"t":"msg","text":"Olá [nome], o pedido #[pedido] está a caminho com [transportadora]. Previsão de entrega: [ETA]. Rastreie: [link de rastreio]."},{"t":"msg","text":"Não vai estar em casa? Responde com um novo horário ou endereço que a gente repassa ao entregador."}]},"payment-reminder":{"en":[{"t":"trigger","text":"COD order delivered but payment not recorded"},{"t":"msg","text":"Hi [name], thanks for your order #[order]. Our records show [amount] is still pending. Could you check and let us know?"},{"t":"delay","v":1440},{"t":"msg","text":"Gentle reminder about [amount] for order #[order]. If you already paid, just send a photo of the receipt here."}],"ar":[{"t":"trigger","text":"طلب دفع عند الاستلام اتسلّم والدفع لسه متسجلش"},{"t":"msg","text":"أهلاً [الاسم]، شكرًا على طلبك رقم [رقم الطلب]. سجلاتنا بتقول إن [المبلغ] لسه معلّق. ممكن تراجع وتقولنا؟"},{"t":"delay","v":1440},{"t":"msg","text":"تذكير لطيف بخصوص [المبلغ] لطلب [رقم الطلب]. لو دفعت خلاص ابعت صورة الإيصال هنا."}],"de":[{"t":"trigger","text":"Nachnahme-Bestellung zugestellt, aber Zahlung nicht verbucht"},{"t":"msg","text":"Hallo [Name], danke für deine Bestellung #[Bestellnummer]. Bei uns ist [Betrag] noch offen. Könntest du das bitte prüfen und uns Bescheid geben?"},{"t":"delay","v":1440},{"t":"msg","text":"Freundliche Erinnerung an [Betrag] für Bestellung #[Bestellnummer]. Falls du schon gezahlt hast, schick einfach ein Foto des Belegs hierhin."}],"es":[{"t":"trigger","text":"Pedido contra reembolso entregado pero pago no registrado"},{"t":"msg","text":"Hola [nombre], gracias por tu pedido #[pedido]. Nuestros registros muestran [importe] aún pendiente. ¿Podrías revisarlo y avisarnos?"},{"t":"delay","v":1440},{"t":"msg","text":"Recordatorio amable sobre [importe] del pedido #[pedido]. Si ya pagaste, solo envía una foto del comprobante aquí."}],"fr":[{"t":"trigger","text":"Commande en contre-remboursement livrée mais paiement non enregistré"},{"t":"msg","text":"Bonjour [nom], merci pour ta commande n°[commande]. Nos registres indiquent [montant] encore en attente. Peux-tu vérifier et nous tenir au courant ?"},{"t":"delay","v":1440},{"t":"msg","text":"Petit rappel concernant [montant] pour la commande n°[commande]. Si tu as déjà payé, envoie simplement une photo du reçu ici."}],"pt":[{"t":"trigger","text":"Pedido em pagamento na entrega entregue, mas pagamento não registrado"},{"t":"msg","text":"Olá [nome], obrigado pelo pedido #[pedido]. Nossos registros mostram [valor] ainda pendente. Você pode verificar e nos avisar?"},{"t":"delay","v":1440},{"t":"msg","text":"Lembrete amigável sobre [valor] do pedido #[pedido]. Se você já pagou, é só mandar uma foto do comprovante aqui."}]},"vip-concierge":{"en":[{"t":"trigger","text":"Message from a customer tagged VIP"},{"t":"cond","text":"Is the customer in the VIP list you chose (for example, 3+ orders)?"},{"t":"msg","text":"Welcome back [name]! Your personal contact is [agent name]. I am letting them know right now."},{"t":"tag","text":"Assign to the named agent and tag: vip-open"},{"t":"delay","v":30},{"t":"msg","text":"If the agent has not replied after 30 minutes, send: \"Thanks for your patience [name], [agent name] will reply shortly.\""}],"ar":[{"t":"trigger","text":"رسالة من عميل موسوم VIP"},{"t":"cond","text":"هل العميل في قايمة VIP اللي اخترتها (مثلًا 3 طلبات أو أكتر)؟"},{"t":"msg","text":"أهلاً بيك تاني يا [الاسم]! مسؤولك الخاص هو [اسم الموظف]. بنبلغه حالًا."},{"t":"tag","text":"عيّن للموظف المسؤول ووسم: vip-مفتوح"},{"t":"delay","v":30},{"t":"msg","text":"لو الموظف مردّش بعد 30 دقيقة ابعت: \"شكرًا لصبرك يا [الاسم]، [اسم الموظف] هيرد عليك حالًا.\""}],"de":[{"t":"trigger","text":"Nachricht von einem Kunden mit VIP-Tag"},{"t":"cond","text":"Ist der Kunde in der von dir gewählten VIP-Liste (z. B. 3+ Bestellungen)?"},{"t":"msg","text":"Willkommen zurück, [Name]! Dein persönlicher Ansprechpartner ist [Mitarbeitername]. Ich informiere ihn gerade."},{"t":"tag","text":"Dem genannten Mitarbeiter zuweisen und Tag: vip-offen"},{"t":"delay","v":30},{"t":"msg","text":"Falls der Mitarbeiter nach 30 Minuten nicht geantwortet hat, sende: „Danke für deine Geduld, [Name], [Mitarbeitername] antwortet gleich.“"}],"es":[{"t":"trigger","text":"Mensaje de un cliente con etiqueta VIP"},{"t":"cond","text":"¿El cliente está en la lista VIP que elegiste (por ejemplo, 3+ pedidos)?"},{"t":"msg","text":"¡Bienvenido de nuevo, [nombre]! Tu contacto personal es [nombre del agente]. Le estoy avisando ahora mismo."},{"t":"tag","text":"Asignar al agente indicado y etiqueta: vip-abierto"},{"t":"delay","v":30},{"t":"msg","text":"Si el agente no ha respondido en 30 minutos, enviar: «Gracias por tu paciencia, [nombre], [nombre del agente] responderá en breve.»"}],"fr":[{"t":"trigger","text":"Message d'un client tagué VIP"},{"t":"cond","text":"Le client est-il dans la liste VIP choisie (par exemple, 3+ commandes) ?"},{"t":"msg","text":"Bon retour [nom] ! Ton contact personnel est [nom de l'agent]. Je le préviens tout de suite."},{"t":"tag","text":"Assigner à l'agent indiqué et tag : vip-ouvert"},{"t":"delay","v":30},{"t":"msg","text":"Si l'agent n'a pas répondu après 30 minutes, envoyer : « Merci pour ta patience [nom], [nom de l'agent] répondra très vite. »"}],"pt":[{"t":"trigger","text":"Mensagem de um cliente com tag VIP"},{"t":"cond","text":"O cliente está na lista VIP que você escolheu (por exemplo, 3+ pedidos)?"},{"t":"msg","text":"Bem-vindo de volta, [nome]! Seu contato pessoal é [nome do atendente]. Estou avisando ele agora mesmo."},{"t":"tag","text":"Atribuir ao atendente indicado e tag: vip-aberto"},{"t":"delay","v":30},{"t":"msg","text":"Se o atendente não responder em 30 minutos, enviar: «Obrigado pela paciência, [nome], [nome do atendente] já vai responder.»"}]},"tiktok-viral-dm-burst":{"en":[{"t":"trigger","text":"Many DMs arrive within a few minutes after a viral video"},{"t":"msg","text":"Instant reply: \"Thanks for the message! We are getting lots of messages. Here is the link from the video: [link].\""},{"t":"cond","text":"Does the message need a human (question about order, complaint, custom request)?"},{"t":"tag","text":"If yes: tag needs-agent and put in the human queue. If no: tag viral-lead"},{"t":"msg","text":"Follow-up an hour later: \"Still interested? Reply YES and we will send details.\""}],"ar":[{"t":"trigger","text":"رسايل كتير بتوصل في دقايق بعد فيديو منتشر"},{"t":"msg","text":"رد فوري: \"شكرًا على رسالتك! جالنا رسايل كتير. ده لينك الفيديو: [اللينك].\""},{"t":"cond","text":"هل الرسالة محتاجة موظف (سؤال عن طلب، شكوى، طلب خاص)؟"},{"t":"tag","text":"لو أيوه: وسم يحتاج-موظف وحطه في طابور الموظفين. لو لأ: وسم عميل-فيروسي"},{"t":"msg","text":"متابعة بعد ساعة: \"لسه مهتم؟ اكتب أيوه وهنبعتلك التفاصيل.\""}],"de":[{"t":"trigger","text":"Viele DMs kommen innerhalb weniger Minuten nach einem viralen Video"},{"t":"msg","text":"Sofortige Antwort: „Danke für die Nachricht! Wir bekommen gerade sehr viele Nachrichten. Hier ist der Link aus dem Video: [Link].“"},{"t":"cond","text":"Braucht die Nachricht einen Menschen (Frage zur Bestellung, Beschwerde, Sonderwunsch)?"},{"t":"tag","text":"Falls ja: Tag braucht-mitarbeiter und in die menschliche Warteschlange. Falls nein: Tag viral-lead"},{"t":"msg","text":"Nachfassen eine Stunde später: „Noch interessiert? Antworte JA und wir schicken die Details.“"}],"es":[{"t":"trigger","text":"Llegan muchos DMs en pocos minutos tras un video viral"},{"t":"msg","text":"Respuesta inmediata: «¡Gracias por el mensaje! Estamos recibiendo muchos mensajes. Aquí está el enlace del video: [enlace].»"},{"t":"cond","text":"¿El mensaje necesita un humano (pregunta sobre pedido, queja, solicitud especial)?"},{"t":"tag","text":"Si sí: etiqueta necesita-agente y pasa a la cola humana. Si no: etiqueta lead-viral"},{"t":"msg","text":"Seguimiento una hora después: «¿Sigues interesado? Responde SÍ y te enviamos los detalles.»"}],"fr":[{"t":"trigger","text":"De nombreux DM arrivent en quelques minutes après une vidéo virale"},{"t":"msg","text":"Réponse immédiate : « Merci pour ton message ! Nous recevons beaucoup de messages. Voici le lien de la vidéo : [lien]. »"},{"t":"cond","text":"Le message a-t-il besoin d'un humain (question sur une commande, plainte, demande spéciale) ?"},{"t":"tag","text":"Si oui : tag besoin-agent et mettre dans la file humaine. Si non : tag lead-viral"},{"t":"msg","text":"Relance une heure plus tard : « Toujours intéressé ? Réponds OUI et on t'envoie les détails. »"}],"pt":[{"t":"trigger","text":"Muitas DMs chegam em poucos minutos após um vídeo viral"},{"t":"msg","text":"Resposta imediata: «Obrigado pela mensagem! Estamos recebendo muitas mensagens. Aqui está o link do vídeo: [link].»"},{"t":"cond","text":"A mensagem precisa de um humano (dúvida sobre pedido, reclamação, pedido especial)?"},{"t":"tag","text":"Se sim: tag precisa-atendente e colocar na fila humana. Se não: tag lead-viral"},{"t":"msg","text":"Follow-up uma hora depois: «Ainda tem interesse? Responde SIM que a gente manda os detalhes.»"}]},"tiktok-product-quiz":{"en":[{"t":"trigger","text":"DM contains \"quiz\" or \"help me choose\""},{"t":"msg","text":"Q1: What do you want to use it for? A) Daily use B) Gift C) Special occasion"},{"t":"msg","text":"Q2: What is your budget? A) Under [X] B) [X] to [Y] C) Over [Y]"},{"t":"msg","text":"Q3: Which style do you prefer? A) Simple B) Bold C) Not sure"},{"t":"cond","text":"Match the answers to a product: A/A/A to [SKU 1], B/B/B to [SKU 2], everything else to [SKU 3]"},{"t":"msg","text":"\"Based on your answers I suggest [product name]: [product link].\""},{"t":"tag","text":"Tag: quiz-[SKU]"}],"ar":[{"t":"trigger","text":"رسالة فيها \"كويز\" أو \"ساعدني أختار\""},{"t":"msg","text":"س1: هتستخدمه في إيه؟ أ) يومي ب) هدية ج) مناسبة خاصة"},{"t":"msg","text":"س2: ميزانيتك كام؟ أ) أقل من [X] ب) من [X] لـ [Y] ج) أكتر من [Y]"},{"t":"msg","text":"س3: تفضل أنهي ستايل؟ أ) بسيط ب) جريء ج) مش متأكد"},{"t":"cond","text":"طابق الإجابات بمنتج: أ/أ/أ لـ [منتج 1]، ب/ب/ب لـ [منتج 2]، غير كده [منتج 3]"},{"t":"msg","text":"\"حسب إجاباتك أرشحلك [اسم المنتج]: [لينك المنتج].\""},{"t":"tag","text":"وسم: كويز-[المنتج]"}],"de":[{"t":"trigger","text":"DM enthält „Quiz“ oder „hilf mir wählen“"},{"t":"msg","text":"F1: Wofür möchtest du es nutzen? A) Täglich B) Geschenk C) Besonderer Anlass"},{"t":"msg","text":"F2: Wie hoch ist dein Budget? A) Unter [X] B) [X] bis [Y] C) Über [Y]"},{"t":"msg","text":"F3: Welchen Stil magst du lieber? A) Schlicht B) Auffällig C) Nicht sicher"},{"t":"cond","text":"Antworten einem Produkt zuordnen: A/A/A → [SKU 1], B/B/B → [SKU 2], alles andere → [SKU 3]"},{"t":"msg","text":"„Basierend auf deinen Antworten empfehle ich [Produktname]: [Produktlink].“"},{"t":"tag","text":"Tag: quiz-[SKU]"}],"es":[{"t":"trigger","text":"DM contiene «quiz» o «ayúdame a elegir»"},{"t":"msg","text":"P1: ¿Para qué lo quieres usar? A) Uso diario B) Regalo C) Ocasión especial"},{"t":"msg","text":"P2: ¿Cuál es tu presupuesto? A) Menos de [X] B) De [X] a [Y] C) Más de [Y]"},{"t":"msg","text":"P3: ¿Qué estilo prefieres? A) Sencillo B) Llamativo C) No estoy seguro"},{"t":"cond","text":"Relacionar las respuestas con un producto: A/A/A → [SKU 1], B/B/B → [SKU 2], lo demás → [SKU 3]"},{"t":"msg","text":"«Según tus respuestas te sugiero [nombre del producto]: [enlace del producto].»"},{"t":"tag","text":"Etiqueta: quiz-[SKU]"}],"fr":[{"t":"trigger","text":"DM contient « quiz » ou « aide-moi à choisir »"},{"t":"msg","text":"Q1 : Pour quoi veux-tu l'utiliser ? A) Usage quotidien B) Cadeau C) Occasion spéciale"},{"t":"msg","text":"Q2 : Quel est ton budget ? A) Moins de [X] B) De [X] à [Y] C) Plus de [Y]"},{"t":"msg","text":"Q3 : Quel style préfères-tu ? A) Simple B) Audacieux C) Je ne sais pas"},{"t":"cond","text":"Associer les réponses à un produit : A/A/A → [SKU 1], B/B/B → [SKU 2], le reste → [SKU 3]"},{"t":"msg","text":"« D'après tes réponses, je te suggère [nom du produit] : [lien du produit]. »"},{"t":"tag","text":"Tag : quiz-[SKU]"}],"pt":[{"t":"trigger","text":"DM contém «quiz» ou «me ajuda a escolher»"},{"t":"msg","text":"P1: Para que você quer usar? A) Uso diário B) Presente C) Ocasião especial"},{"t":"msg","text":"P2: Qual é seu orçamento? A) Menos de [X] B) De [X] a [Y] C) Mais de [Y]"},{"t":"msg","text":"P3: Qual estilo você prefere? A) Simples B) Ousado C) Não tenho certeza"},{"t":"cond","text":"Relacionar as respostas a um produto: A/A/A → [SKU 1], B/B/B → [SKU 2], o resto → [SKU 3]"},{"t":"msg","text":"«Pelas suas respostas, sugiro [nome do produto]: [link do produto].»"},{"t":"tag","text":"Tag: quiz-[SKU]"}]},"tiktok-creator-reply":{"en":[{"t":"trigger","text":"Comment on a video that contains a question mark or \"how\""},{"t":"msg","text":"(Public reply) Good question, [name]! I sent you the full answer in a DM."},{"t":"msg","text":"Hi [name]! Short answer: [answer]. More details here: [deep link]"},{"t":"tag","text":"Tag: tiktok-question"}],"ar":[{"t":"trigger","text":"تعليق على فيديو فيه علامة استفهام أو \"إزاي\""},{"t":"msg","text":"(رد علني) سؤال حلو يا [الاسم]! بعتلك الإجابة كاملة على الخاص."},{"t":"msg","text":"أهلاً [الاسم]! الإجابة المختصرة: [الإجابة]. تفاصيل أكتر هنا: [اللينك]"},{"t":"tag","text":"وسم: سؤال-تيك-توك"}],"de":[{"t":"trigger","text":"Kommentar unter einem Video mit Fragezeichen oder „wie“"},{"t":"msg","text":"(Öffentliche Antwort) Gute Frage, [Name]! Ich habe dir die ausführliche Antwort per DM geschickt."},{"t":"msg","text":"Hallo [Name]! Kurze Antwort: [Antwort]. Mehr Details hier: [Deeplink]"},{"t":"tag","text":"Tag: tiktok-frage"}],"es":[{"t":"trigger","text":"Comentario en un video que contiene signo de interrogación o «cómo»"},{"t":"msg","text":"(Respuesta pública) Buena pregunta, [nombre]! Te envié la respuesta completa por DM."},{"t":"msg","text":"¡Hola [nombre]! Respuesta corta: [respuesta]. Más detalles aquí: [enlace directo]"},{"t":"tag","text":"Etiqueta: pregunta-tiktok"}],"fr":[{"t":"trigger","text":"Commentaire sur une vidéo contenant un point d'interrogation ou « comment »"},{"t":"msg","text":"(Réponse publique) Bonne question, [nom] ! Je t'ai envoyé la réponse complète en DM."},{"t":"msg","text":"Bonjour [nom] ! Réponse courte : [réponse]. Plus de détails ici : [lien direct]"},{"t":"tag","text":"Tag : question-tiktok"}],"pt":[{"t":"trigger","text":"Comentário em um vídeo contendo ponto de interrogação ou «como»"},{"t":"msg","text":"(Resposta pública) Boa pergunta, [nome]! Te mandei a resposta completa por DM."},{"t":"msg","text":"Olá [nome]! Resposta curta: [resposta]. Mais detalhes aqui: [link direto]"},{"t":"tag","text":"Tag: pergunta-tiktok"}]},"sound-trend-giveaway":{"en":[{"t":"trigger","text":"Comment with the giveaway keyword on the giveaway video"},{"t":"cond","text":"Does the person follow the account and meet the rules (one entry per person)?"},{"t":"msg","text":"\"You are in, [name]! Winners are announced on [date]. Good luck!\""},{"t":"tag","text":"Tag: giveaway-entry-[campaign]"},{"t":"msg","text":"On the draw date, pick winners at random from tagged entries and DM them: \"Congratulations [name], you won [prize]! Reply with your details to claim it.\""},{"t":"msg","text":"Publish the winners in a pinned comment and a post, with the rules link: [rules link]"}],"ar":[{"t":"trigger","text":"تعليق بكلمة السحب على فيديو السحب"},{"t":"cond","text":"هل الشخص متابع للحساب وملتزم بالقواعد (مشاركة واحدة للشخص)؟"},{"t":"msg","text":"\"اتسجلت يا [الاسم]! الفايزين بيتعلنوا يوم [التاريخ]. بالتوفيق!\""},{"t":"tag","text":"وسم: مشارك-سحب-[الحملة]"},{"t":"msg","text":"يوم السحب اختار الفايزين عشوائيًا من المشاركين الموسومين وابعتلهم: \"مبروك يا [الاسم]، كسبت [الجايزة]! ابعت بياناتك لاستلامها.\""},{"t":"msg","text":"انشر الفايزين في كومنت مثبت وبوست مع لينك القواعد: [لينك القواعد]"}],"de":[{"t":"trigger","text":"Kommentar mit dem Gewinnspiel-Schlüsselwort unter dem Gewinnspiel-Video"},{"t":"cond","text":"Folgt die Person dem Konto und erfüllt sie die Regeln (eine Teilnahme pro Person)?"},{"t":"msg","text":"„Du bist dabei, [Name]! Die Gewinner werden am [Datum] bekannt gegeben. Viel Glück!“"},{"t":"tag","text":"Tag: gewinnspiel-[Kampagne]"},{"t":"msg","text":"Am Ziehungstag Gewinner per Zufall aus den markierten Teilnahmen ziehen und per DM schreiben: „Glückwunsch, [Name], du hast [Preis] gewonnen! Antworte mit deinen Daten zum Einlösen.“"},{"t":"msg","text":"Die Gewinner in einem angepinnten Kommentar und einem Beitrag verkünden, mit Regel-Link: [Regel-Link]"}],"es":[{"t":"trigger","text":"Comentario con la palabra clave del sorteo en el video del sorteo"},{"t":"cond","text":"¿La persona sigue la cuenta y cumple las reglas (una participación por persona)?"},{"t":"msg","text":"«¡Ya participas, [nombre]! Los ganadores se anuncian el [fecha]. ¡Suerte!»"},{"t":"tag","text":"Etiqueta: sorteo-[campaña]"},{"t":"msg","text":"El día del sorteo, elegir ganadores al azar entre las participaciones etiquetadas y enviarles DM: «¡Felicidades [nombre], ganaste [premio]! Responde con tus datos para reclamarlo.»"},{"t":"msg","text":"Publicar los ganadores en un comentario fijado y una publicación, con el enlace de las reglas: [enlace de reglas]"}],"fr":[{"t":"trigger","text":"Commentaire avec le mot-clé du concours sur la vidéo du concours"},{"t":"cond","text":"La personne suit-elle le compte et respecte-t-elle les règles (une participation par personne) ?"},{"t":"msg","text":"« Tu participes, [nom] ! Les gagnants sont annoncés le [date]. Bonne chance ! »"},{"t":"tag","text":"Tag : concours-[campagne]"},{"t":"msg","text":"Le jour du tirage, choisir les gagnants au hasard parmi les participations taguées et leur écrire en DM : « Félicitations [nom], tu as gagné [prix] ! Réponds avec tes coordonnées pour le réclamer. »"},{"t":"msg","text":"Annoncer les gagnants dans un commentaire épinglé et une publication, avec le lien du règlement : [lien du règlement]"}],"pt":[{"t":"trigger","text":"Comentário com a palavra-chave do sorteio no vídeo do sorteio"},{"t":"cond","text":"A pessoa segue a conta e cumpre as regras (uma participação por pessoa)?"},{"t":"msg","text":"«Você está participando, [nome]! Os vencedores serão anunciados em [data]. Boa sorte!»"},{"t":"tag","text":"Tag: sorteio-[campanha]"},{"t":"msg","text":"No dia do sorteio, escolher os vencedores aleatoriamente entre as participações marcadas e mandar DM: «Parabéns [nome], você ganhou [prêmio]! Responde com seus dados para resgatar.»"},{"t":"msg","text":"Publicar os vencedores em um comentário fixado e um post, com o link das regras: [link das regras]"}]},"cart-recovery-in-dm":{"en":[{"t":"trigger","text":"Customer who agreed to messages leaves items in the cart"},{"t":"delay","v":60},{"t":"msg","text":"Hi [name], you left [product] in your cart. Need help finishing your order? Your cart: [cart link]"},{"t":"delay","v":1440},{"t":"msg","text":"Your cart is still saved. [Optional: free delivery this week]. Reply \"STOP\" to stop these reminders."}],"ar":[{"t":"trigger","text":"عميل موافق على الرسايل سابق منتجات في السلة"},{"t":"delay","v":60},{"t":"msg","text":"أهلاً [الاسم]، سبت [المنتج] في السلة. محتاج مساعدة تكمّل الطلب؟ السلة: [لينك السلة]"},{"t":"delay","v":1440},{"t":"msg","text":"السلة لسه محفوظة. [اختياري: توصيل مجاني الأسبوع ده]. اكتب \"إيقاف\" لإيقاف التذكيرات."}],"de":[{"t":"trigger","text":"Kunde, der Nachrichten zugestimmt hat, lässt Artikel im Warenkorb"},{"t":"delay","v":60},{"t":"msg","text":"Hallo [Name], du hast [Produkt] im Warenkorb gelassen. Brauchst du Hilfe beim Abschließen? Dein Warenkorb: [Warenkorb-Link]"},{"t":"delay","v":1440},{"t":"msg","text":"Dein Warenkorb ist noch gespeichert. [Optional: gratis Lieferung diese Woche]. Antworte „STOPP“, um diese Erinnerungen zu stoppen."}],"es":[{"t":"trigger","text":"Cliente que aceptó mensajes deja artículos en el carrito"},{"t":"delay","v":60},{"t":"msg","text":"Hola [nombre], dejaste [producto] en tu carrito. ¿Necesitas ayuda para terminar tu pedido? Tu carrito: [enlace del carrito]"},{"t":"delay","v":1440},{"t":"msg","text":"Tu carrito sigue guardado. [Opcional: envío gratis esta semana]. Responde «STOP» para dejar de recibir estos recordatorios."}],"fr":[{"t":"trigger","text":"Un client ayant accepté les messages laisse des articles dans son panier"},{"t":"delay","v":60},{"t":"msg","text":"Bonjour [nom], tu as laissé [produit] dans ton panier. Besoin d'aide pour finaliser ta commande ? Ton panier : [lien du panier]"},{"t":"delay","v":1440},{"t":"msg","text":"Ton panier est toujours enregistré. [Optionnel : livraison offerte cette semaine]. Réponds « STOP » pour arrêter ces rappels."}],"pt":[{"t":"trigger","text":"Cliente que aceitou mensagens deixa itens no carrinho"},{"t":"delay","v":60},{"t":"msg","text":"Olá [nome], você deixou [produto] no seu carrinho. Precisa de ajuda pra finalizar o pedido? Seu carrinho: [link do carrinho]"},{"t":"delay","v":1440},{"t":"msg","text":"Seu carrinho ainda está salvo. [Opcional: entrega grátis esta semana]. Responde «PARAR» para parar esses lembretes."}]},"bundle-upsell":{"en":[{"t":"trigger","text":"Customer adds [product] to an order"},{"t":"msg","text":"Nice choice, [name]! Many customers add [companion product] with it for [bundle price] instead of [separate price]."},{"t":"cond","text":"Did the customer reply \"ADD\" or tap the add button?"},{"t":"tag","text":"Yes: add the companion product to the order and tag \"bundle\". No: continue to checkout"}],"ar":[{"t":"trigger","text":"عميل أضاف [المنتج] لطلب"},{"t":"msg","text":"اختيار حلو يا [الاسم]! عملاء كتير بيضيفوا [المنتج المكمل] معاه بـ [سعر الباقة] بدل [السعر منفصل]."},{"t":"cond","text":"هل العميل ردّ \"أضف\" أو ضغط زر الإضافة؟"},{"t":"tag","text":"أيوه: أضف المنتج المكمل للطلب ووسم \"باقة\". لأ: كمّل للدفع"}],"de":[{"t":"trigger","text":"Kunde fügt [Produkt] einer Bestellung hinzu"},{"t":"msg","text":"Gute Wahl, [Name]! Viele Kunden nehmen [Ergänzungsprodukt] dazu, für [Bundle-Preis] statt [Einzelpreis]."},{"t":"cond","text":"Hat der Kunde „HINZUFÜGEN“ geantwortet oder den Hinzufügen-Button getippt?"},{"t":"tag","text":"Ja: Ergänzungsprodukt zur Bestellung hinzufügen und Tag „bundle“. Nein: weiter zum Checkout"}],"es":[{"t":"trigger","text":"El cliente añade [producto] a un pedido"},{"t":"msg","text":"¡Buena elección, [nombre]! Muchos clientes añaden [producto complementario] por [precio de bundle] en vez de [precio por separado]."},{"t":"cond","text":"¿El cliente respondió «AÑADIR» o tocó el botón de añadir?"},{"t":"tag","text":"Sí: añadir el producto complementario al pedido y etiqueta «bundle». No: continuar al pago"}],"fr":[{"t":"trigger","text":"Le client ajoute [produit] à une commande"},{"t":"msg","text":"Bon choix, [nom] ! Beaucoup de clients ajoutent [produit complémentaire] avec, pour [prix du bundle] au lieu de [prix séparé]."},{"t":"cond","text":"Le client a-t-il répondu « AJOUTER » ou touché le bouton d'ajout ?"},{"t":"tag","text":"Oui : ajouter le produit complémentaire à la commande et tag « bundle ». Non : continuer vers le paiement"}],"pt":[{"t":"trigger","text":"Cliente adiciona [produto] a um pedido"},{"t":"msg","text":"Boa escolha, [nome]! Muitos clientes levam [produto complementar] junto, por [preço do bundle] em vez de [preço separado]."},{"t":"cond","text":"O cliente respondeu «ADICIONAR» ou tocou no botão de adicionar?"},{"t":"tag","text":"Sim: adicionar o produto complementar ao pedido e tag «bundle». Não: seguir para o pagamento"}]},"size-guide-assistant":{"en":[{"t":"trigger","text":"DM asks about size or fit"},{"t":"msg","text":"Happy to help, [name]! What is your height and weight, and how do you like it to fit (snug, regular, loose)?"},{"t":"cond","text":"Match to the size chart: which size fits the measurements and preference?"},{"t":"msg","text":"\"I suggest size [size]. Our size chart is here: [chart link]. If you are between sizes, most people go [up/down].\""},{"t":"tag","text":"Tag: size-[size]"}],"ar":[{"t":"trigger","text":"رسالة بتسأل عن المقاس"},{"t":"msg","text":"يسعدني أساعدك يا [الاسم]! طولك ووزنك كام، وبتحب المقاس ضيق ولا عادي ولا واسع؟"},{"t":"cond","text":"طابق مع جدول المقاسات: أنهي مقاس مناسب للقياسات والتفضيل؟"},{"t":"msg","text":"\"أرشحلك مقاس [المقاس]. جدول المقاسات هنا: [اللينك]. لو بين مقاسين، أغلب الناس بتختار [أكبر/أصغر].\""},{"t":"tag","text":"وسم: مقاس-[المقاس]"}],"de":[{"t":"trigger","text":"DM fragt nach Größe oder Passform"},{"t":"msg","text":"Gern, [Name]! Wie groß und wie schwer bist du, und wie soll es sitzen (eng, normal, locker)?"},{"t":"cond","text":"Mit der Größentabelle abgleichen: welche Größe passt zu Maßen und Wunsch?"},{"t":"msg","text":"„Ich empfehle Größe [Größe]. Unsere Größentabelle ist hier: [Tabellen-Link]. Wenn du zwischen zwei Größen liegst, nehmen die meisten [eine größer/eine kleiner].“"},{"t":"tag","text":"Tag: größe-[Größe]"}],"es":[{"t":"trigger","text":"DM pregunta por talla o ajuste"},{"t":"msg","text":"¡Con gusto, [nombre]! ¿Cuál es tu altura y peso, y cómo te gusta el ajuste (ceñido, normal, holgado)?"},{"t":"cond","text":"Cruzar con la guía de tallas: ¿qué talla encaja con las medidas y la preferencia?"},{"t":"msg","text":"«Te sugiero la talla [talla]. Nuestra guía de tallas está aquí: [enlace de la guía]. Si estás entre dos tallas, la mayoría elige [una más/una menos].»"},{"t":"tag","text":"Etiqueta: talla-[talla]"}],"fr":[{"t":"trigger","text":"DM pose une question sur la taille ou la coupe"},{"t":"msg","text":"Avec plaisir, [nom] ! Quelle est ta taille et ton poids, et comment aimes-tu la coupe (près du corps, normale, ample) ?"},{"t":"cond","text":"Croiser avec le guide des tailles : quelle taille correspond aux mensurations et à la préférence ?"},{"t":"msg","text":"« Je te suggère la taille [taille]. Notre guide des tailles est ici : [lien du guide]. Si tu es entre deux tailles, la plupart prennent [au-dessus/en-dessous]. »"},{"t":"tag","text":"Tag : taille-[taille]"}],"pt":[{"t":"trigger","text":"DM pergunta sobre tamanho ou caimento"},{"t":"msg","text":"Com prazer, [nome]! Qual sua altura e peso, e como você gosta do caimento (justo, normal, largo)?"},{"t":"cond","text":"Cruzar com a tabela de medidas: qual tamanho combina com as medidas e a preferência?"},{"t":"msg","text":"«Sugiro o tamanho [tamanho]. Nossa tabela de medidas está aqui: [link da tabela]. Se você fica entre dois tamanhos, a maioria escolhe [um acima/um abaixo].»"},{"t":"tag","text":"Tag: tamanho-[tamanho]"}]},"post-purchase-review":{"en":[{"t":"trigger","text":"Order delivered"},{"t":"delay","v":2880},{"t":"msg","text":"Hi [name], how is your [product]? If you have a minute, we would love a review: [review link]."},{"t":"msg","text":"When you need more, reorder in one tap: [reorder link]. Reply \"STOP\" to opt out of messages."}],"ar":[{"t":"trigger","text":"الطلب اتسلّم"},{"t":"delay","v":2880},{"t":"msg","text":"أهلاً [الاسم]، [المنتج] عامل معاك إيه؟ لو عندك دقيقة هنفرح بتقييمك: [لينك التقييم]."},{"t":"msg","text":"لما تحتاج تاني، اطلب بضغطة واحدة: [لينك إعادة الطلب]. اكتب \"إيقاف\" لإلغاء الرسايل."}],"de":[{"t":"trigger","text":"Bestellung zugestellt"},{"t":"delay","v":2880},{"t":"msg","text":"Hallo [Name], wie gefällt dir dein [Produkt]? Wenn du eine Minute hast, würden wir uns über eine Bewertung freuen: [Bewertungslink]."},{"t":"msg","text":"Wenn du Nachschub brauchst, bestelle mit einem Tippen nach: [Nachbestell-Link]. Antworte „STOPP“, um keine Nachrichten mehr zu erhalten."}],"es":[{"t":"trigger","text":"Pedido entregado"},{"t":"delay","v":2880},{"t":"msg","text":"Hola [nombre], ¿qué tal tu [producto]? Si tienes un minuto, nos encantaría una reseña: [enlace de reseña]."},{"t":"msg","text":"Cuando necesites más, vuelve a pedir con un toque: [enlace de recompra]. Responde «STOP» para dejar de recibir mensajes."}],"fr":[{"t":"trigger","text":"Commande livrée"},{"t":"delay","v":2880},{"t":"msg","text":"Bonjour [nom], comment te plaît ton [produit] ? Si tu as une minute, un avis nous ferait très plaisir : [lien d'avis]."},{"t":"msg","text":"Quand tu en auras besoin de plus, recommande en un geste : [lien de rachat]. Réponds « STOP » pour ne plus recevoir de messages."}],"pt":[{"t":"trigger","text":"Pedido entregue"},{"t":"delay","v":2880},{"t":"msg","text":"Olá [nome], como está seu [produto]? Se tiver um minuto, adoraríamos uma avaliação: [link de avaliação]."},{"t":"msg","text":"Quando precisar de mais, peça de novo com um toque: [link de recompra]. Responde «PARAR» para sair das mensagens."}]},"restock-waitlist":{"en":[{"t":"trigger","text":"Message asking about a sold-out item"},{"t":"msg","text":"[product] is sold out right now. Want to join the waitlist? Reply \"YES\" and we will message you first when it is back."},{"t":"tag","text":"Tag: waitlist-[product]"},{"t":"msg","text":"When stock returns, message the waitlist in order: \"[product] is back, [name]! Link: [link]. We hold it for you for [hours] hours.\""}],"ar":[{"t":"trigger","text":"رسالة بتسأل عن منتج خلصان"},{"t":"msg","text":"[المنتج] خلصان دلوقتي. تحب تدخل قايمة الانتظار؟ اكتب \"أيوه\" وهنبلغك الأول لما يرجع."},{"t":"tag","text":"وسم: انتظار-[المنتج]"},{"t":"msg","text":"لما المخزون يرجع ابعت للقايمة بالترتيب: \"[المنتج] رجع يا [الاسم]! اللينك: [اللينك]. هنحجزهولك [عدد] ساعات.\""}],"de":[{"t":"trigger","text":"Nachricht fragt nach einem ausverkauften Artikel"},{"t":"msg","text":"[Produkt] ist gerade ausverkauft. Möchtest du auf die Warteliste? Antworte „JA“ und wir schreiben dir zuerst, wenn es wieder da ist."},{"t":"tag","text":"Tag: warteliste-[Produkt]"},{"t":"msg","text":"Wenn der Bestand zurückkommt, die Warteliste der Reihe nach anschreiben: „[Produkt] ist wieder da, [Name]! Link: [Link]. Wir halten es [Stunden] Stunden für dich zurück.“"}],"es":[{"t":"trigger","text":"Mensaje preguntando por un artículo agotado"},{"t":"msg","text":"[producto] está agotado ahora mismo. ¿Quieres unirte a la lista de espera? Responde «SÍ» y te escribiremos primero cuando vuelva."},{"t":"tag","text":"Etiqueta: espera-[producto]"},{"t":"msg","text":"Cuando vuelva el stock, escribir a la lista de espera en orden: «¡[producto] volvió, [nombre]! Enlace: [enlace]. Te lo guardamos por [horas] horas.»"}],"fr":[{"t":"trigger","text":"Message demandant un article épuisé"},{"t":"msg","text":"[produit] est épuisé pour le moment. Tu veux rejoindre la liste d'attente ? Réponds « OUI » et on t'écrira en premier quand il sera de retour."},{"t":"tag","text":"Tag : attente-[produit]"},{"t":"msg","text":"Au retour du stock, écrire à la liste d'attente dans l'ordre : « [produit] est de retour, [nom] ! Lien : [lien]. On te le garde pendant [heures] heures. »"}],"pt":[{"t":"trigger","text":"Mensagem perguntando sobre um item esgotado"},{"t":"msg","text":"[produto] está esgotado no momento. Quer entrar na lista de espera? Responde «SIM» que a gente te avisa primeiro quando voltar."},{"t":"tag","text":"Tag: espera-[produto]"},{"t":"msg","text":"Quando o estoque voltar, avisar a lista de espera em ordem: «[produto] voltou, [nome]! Link: [link]. Guardamos pra você por [horas] horas.»"}]},"discount-discipline":{"en":[{"t":"trigger","text":"Message asks for a discount"},{"t":"msg","text":"Thanks for asking, [name]! We keep our prices fair for everyone. Here is what comes with [product]: [value points, e.g. warranty, free delivery, gift]."},{"t":"cond","text":"Does the customer still object, or mention a real issue (price mistake, damaged item)?"},{"t":"msg","text":"Yes: \"I understand. I am bringing in a teammate who can look at this properly.\""},{"t":"tag","text":"Yes: tag needs-agent. No: tag value-offered"}],"ar":[{"t":"trigger","text":"رسالة بتطلب خصم"},{"t":"msg","text":"شكرًا على سؤالك يا [الاسم]! أسعارنا عادلة للكل. ده اللي بييجي مع [المنتج]: [نقاط القيمة مثل الضمان، التوصيل المجاني، هدية]."},{"t":"cond","text":"هل العميل لسه معترض أو ذكر مشكلة حقيقية (غلط في السعر، منتج تالف)؟"},{"t":"msg","text":"أيوه: \"فاهمك. هجيب زميل يبص في الموضوع كويس.\""},{"t":"tag","text":"أيوه: وسم يحتاج-موظف. لأ: وسم تم-عرض-القيمة"}],"de":[{"t":"trigger","text":"Nachricht bittet um Rabatt"},{"t":"msg","text":"Danke für die Frage, [Name]! Wir halten unsere Preise für alle fair. Das ist bei [Produkt] dabei: [Pluspunkte, z. B. Garantie, gratis Lieferung, Geschenk]."},{"t":"cond","text":"Besteht der Kunde weiter darauf oder nennt er ein echtes Problem (Preisfehler, beschädigter Artikel)?"},{"t":"msg","text":"Ja: „Verstehe. Ich hole einen Kollegen dazu, der sich das richtig ansehen kann.“"},{"t":"tag","text":"Ja: Tag braucht-mitarbeiter. Nein: Tag mehrwert-angeboten"}],"es":[{"t":"trigger","text":"Mensaje pidiendo un descuento"},{"t":"msg","text":"¡Gracias por preguntar, [nombre]! Mantenemos precios justos para todos. Esto incluye [producto]: [puntos de valor, p. ej. garantía, envío gratis, regalo]."},{"t":"cond","text":"¿El cliente insiste o menciona un problema real (error de precio, artículo dañado)?"},{"t":"msg","text":"Sí: «Te entiendo. Voy a traer a un compañero que pueda revisarlo bien.»"},{"t":"tag","text":"Sí: etiqueta necesita-agente. No: etiqueta valor-ofrecido"}],"fr":[{"t":"trigger","text":"Message demandant une remise"},{"t":"msg","text":"Merci de ta demande, [nom] ! Nous gardons des prix justes pour tout le monde. Voici ce qui est inclus avec [produit] : [atouts, p. ex. garantie, livraison offerte, cadeau]."},{"t":"cond","text":"Le client insiste-t-il, ou mentionne-t-il un vrai problème (erreur de prix, article abîmé) ?"},{"t":"msg","text":"Oui : « Je comprends. Je fais venir un collègue qui pourra regarder ça correctement. »"},{"t":"tag","text":"Oui : tag besoin-agent. Non : tag valeur-proposée"}],"pt":[{"t":"trigger","text":"Mensagem pedindo desconto"},{"t":"msg","text":"Obrigado por perguntar, [nome]! Mantemos preços justos para todos. Isso vem com [produto]: [pontos de valor, ex.: garantia, entrega grátis, brinde]."},{"t":"cond","text":"O cliente insiste ou menciona um problema real (erro de preço, item danificado)?"},{"t":"msg","text":"Sim: «Entendo. Vou chamar um colega que pode analisar isso direito.»"},{"t":"tag","text":"Sim: tag precisa-atendente. Não: tag valor-oferecido"}]},"pre-order-deposit":{"en":[{"t":"trigger","text":"Customer wants to pre-order a product"},{"t":"msg","text":"Great, [name]! [product] ships around [date]. A deposit of [amount] reserves yours. The balance is due before shipping."},{"t":"msg","text":"Pay the deposit here: [secure payment link]. Terms and refund policy: [policy link]."},{"t":"cond","text":"Is the deposit payment confirmed in your payment system?"},{"t":"tag","text":"Yes: tag deposit-paid and send a confirmation with the order number. No: remind once after 24 hours"}],"ar":[{"t":"trigger","text":"عميل عايز يحجز منتج مسبقًا"},{"t":"msg","text":"تمام يا [الاسم]! [المنتج] هيتشحن حوالي [التاريخ]. عربون [المبلغ] بيحجز منتجك. والباقي قبل الشحن."},{"t":"msg","text":"ادفع العربون من هنا: [لينك الدفع الآمن]. الشروط وسياسة الاسترجاع: [لينك السياسة]."},{"t":"cond","text":"هل دفع العربون اتأكد في نظام الدفع؟"},{"t":"tag","text":"أيوه: وسم عربون-مدفوع وابعت تأكيد برقم الطلب. لأ: ذكّر مرة بعد 24 ساعة"}],"de":[{"t":"trigger","text":"Kunde möchte ein Produkt vorbestellen"},{"t":"msg","text":"Super, [Name]! [Produkt] wird etwa am [Datum] verschickt. Eine Anzahlung von [Betrag] reserviert deins. Der Rest ist vor dem Versand fällig."},{"t":"msg","text":"Zahle die Anzahlung hier: [sicherer Zahlungslink]. Bedingungen und Erstattungsrichtlinie: [Richtlinien-Link]."},{"t":"cond","text":"Ist die Anzahlung in deinem Zahlungssystem bestätigt?"},{"t":"tag","text":"Ja: Tag anzahlung-bezahlt und eine Bestätigung mit der Bestellnummer schicken. Nein: nach 24 Stunden einmal erinnern"}],"es":[{"t":"trigger","text":"El cliente quiere reservar un producto en preventa"},{"t":"msg","text":"¡Genial, [nombre]! [producto] se envía alrededor del [fecha]. Un anticipo de [importe] reserva el tuyo. El resto se paga antes del envío."},{"t":"msg","text":"Paga el anticipo aquí: [enlace de pago seguro]. Términos y política de reembolso: [enlace de política]."},{"t":"cond","text":"¿El anticipo está confirmado en tu sistema de pagos?"},{"t":"tag","text":"Sí: etiqueta anticipo-pagado y enviar confirmación con el número de pedido. No: recordar una vez tras 24 horas"}],"fr":[{"t":"trigger","text":"Le client veut précommander un produit"},{"t":"msg","text":"Super, [nom] ! [produit] est expédié vers le [date]. Un acompte de [montant] réserve le tien. Le solde est dû avant l'expédition."},{"t":"msg","text":"Paie l'acompte ici : [lien de paiement sécurisé]. Conditions et politique de remboursement : [lien des conditions]."},{"t":"cond","text":"L'acompte est-il confirmé dans ton système de paiement ?"},{"t":"tag","text":"Oui : tag acompte-payé et envoyer une confirmation avec le numéro de commande. Non : relancer une fois après 24 heures"}],"pt":[{"t":"trigger","text":"Cliente quer fazer pré-venda de um produto"},{"t":"msg","text":"Ótimo, [nome]! [produto] será enviado por volta de [data]. Um sinal de [valor] reserva o seu. O restante é devido antes do envio."},{"t":"msg","text":"Pague o sinal aqui: [link de pagamento seguro]. Termos e política de reembolso: [link da política]."},{"t":"cond","text":"O sinal está confirmado no seu sistema de pagamentos?"},{"t":"tag","text":"Sim: tag sinal-pago e enviar confirmação com o número do pedido. Não: lembrar uma vez após 24 horas"}]},"loyalty-reorder-nudge":{"en":[{"t":"trigger","text":"[X] days since the last order of a repeat product"},{"t":"msg","text":"Hi [name], it has been a while since you got [product]. Running low? Reorder here: [reorder link]."},{"t":"delay","v":4320},{"t":"msg","text":"If no reply after 3 days: \"A small thank-you for being a regular: [loyalty perk]. Reply STOP to opt out.\""}],"ar":[{"t":"trigger","text":"مرّ [X] يوم على آخر طلب لمنتج بيتكرر"},{"t":"msg","text":"أهلاً [الاسم]، من فترة اشتريت [المنتج]. قرّب يخلص؟ اطلبه تاني من هنا: [لينك إعادة الطلب]."},{"t":"delay","v":4320},{"t":"msg","text":"لو مفيش رد بعد 3 أيام: \"هدية بسيطة لأنك عميل دايم: [مزية الولاء]. اكتب إيقاف لإلغاء الرسايل.\""}],"de":[{"t":"trigger","text":"[X] Tage seit der letzten Bestellung eines Verbrauchsprodukts"},{"t":"msg","text":"Hallo [Name], dein letztes [Produkt] ist schon eine Weile her. Wird es knapp? Hier nachbestellen: [Nachbestell-Link]."},{"t":"delay","v":4320},{"t":"msg","text":"Falls nach 3 Tagen keine Antwort: „Ein kleines Dankeschön für deine Treue: [Treue-Vorteil]. Antworte STOPP zum Abmelden.“"}],"es":[{"t":"trigger","text":"[X] días desde el último pedido de un producto recurrente"},{"t":"msg","text":"Hola [nombre], ya hace tiempo de tu último [producto]. ¿Se está acabando? Pídelo de nuevo aquí: [enlace de recompra]."},{"t":"delay","v":4320},{"t":"msg","text":"Si no hay respuesta tras 3 días: «Un pequeño agradecimiento por ser cliente habitual: [beneficio de fidelidad]. Responde STOP para darte de baja.»"}],"fr":[{"t":"trigger","text":"[X] jours depuis la dernière commande d'un produit récurrent"},{"t":"msg","text":"Bonjour [nom], cela fait un moment depuis ton dernier [produit]. Bientôt épuisé ? Recommande ici : [lien de rachat]."},{"t":"delay","v":4320},{"t":"msg","text":"Si pas de réponse après 3 jours : « Un petit merci pour ta fidélité : [avantage fidélité]. Réponds STOP pour te désinscrire. »"}],"pt":[{"t":"trigger","text":"[X] dias desde o último pedido de um produto recorrente"},{"t":"msg","text":"Olá [nome], já faz um tempo do seu último [produto]. Tá acabando? Peça de novo aqui: [link de recompra]."},{"t":"delay","v":4320},{"t":"msg","text":"Se não responder em 3 dias: «Um mimo de agradecimento por ser cliente fiel: [benefício de fidelidade]. Responde PARAR para sair.»"}]},"human-handoff":{"en":[{"t":"trigger","text":"Message mentions refund, complaint, VIP, or \"talk to a person\""},{"t":"msg","text":"Of course, [name]. I am passing this to a teammate now. They will reply in [time]. You do not need to repeat anything."},{"t":"tag","text":"Pause the bot, assign to an agent with the chat summary, tag: needs-agent"}],"ar":[{"t":"trigger","text":"رسالة فيها استرجاع أو شكوى أو VIP أو \"عايز أكلم حد\""},{"t":"msg","text":"طبعًا يا [الاسم]. بحوّل المحادثة لزميل حالًا. هيرد عليك خلال [المدة]. مش محتاج تعيد أي حاجة."},{"t":"tag","text":"أوقف البوت، عيّن لموظف مع ملخص المحادثة، وسم: يحتاج-موظف"}],"de":[{"t":"trigger","text":"Nachricht erwähnt Erstattung, Beschwerde, VIP oder „mit einem Menschen sprechen“"},{"t":"msg","text":"Natürlich, [Name]. Ich gebe das gerade an einen Kollegen weiter. Er antwortet innerhalb von [Zeit]. Du musst nichts wiederholen."},{"t":"tag","text":"Bot pausieren, einem Mitarbeiter mit Chat-Zusammenfassung zuweisen, Tag: braucht-mitarbeiter"}],"es":[{"t":"trigger","text":"El mensaje menciona reembolso, queja, VIP o «hablar con una persona»"},{"t":"msg","text":"Por supuesto, [nombre]. Lo estoy pasando a un compañero ahora. Responderá en [tiempo]. No necesitas repetir nada."},{"t":"tag","text":"Pausar el bot, asignar a un agente con el resumen del chat, etiqueta: necesita-agente"}],"fr":[{"t":"trigger","text":"Le message mentionne remboursement, plainte, VIP ou « parler à une personne »"},{"t":"msg","text":"Bien sûr, [nom]. Je transmets ça à un collègue maintenant. Il répondra sous [délai]. Tu n'as rien à répéter."},{"t":"tag","text":"Mettre le bot en pause, assigner à un agent avec le résumé de la conversation, tag : besoin-agent"}],"pt":[{"t":"trigger","text":"Mensagem menciona reembolso, reclamação, VIP ou «falar com uma pessoa»"},{"t":"msg","text":"Claro, [nome]. Estou passando isso para um colega agora. Ele responde em [tempo]. Você não precisa repetir nada."},{"t":"tag","text":"Pausar o bot, atribuir a um atendente com o resumo da conversa, tag: precisa-atendente"}]},"refund-triage":{"en":[{"t":"trigger","text":"Message mentions refund or return"},{"t":"msg","text":"Sorry about that, [name]. To help quickly, please send your order number and tell me what went wrong."},{"t":"msg","text":"Please also send a photo of the item or the problem."},{"t":"cond","text":"Reason: damaged / wrong item / changed mind / other"},{"t":"tag","text":"Route: damaged and wrong item to the quality team, changed mind to the returns team. Tag: refund-[reason]"}],"ar":[{"t":"trigger","text":"رسالة فيها استرجاع أو ترجيع"},{"t":"msg","text":"آسفين على كده يا [الاسم]. عشان نساعدك بسرعة ابعت رقم الطلب وقولي إيه المشكلة."},{"t":"msg","text":"وابعت كمان صورة للمنتج أو المشكلة."},{"t":"cond","text":"السبب: تالف / منتج غلط / غيّر رأيه / غير ذلك"},{"t":"tag","text":"وجّه: التالف والغلط لفريق الجودة، تغيير الرأي لفريق المرتجعات. وسم: استرجاع-[السبب]"}],"de":[{"t":"trigger","text":"Nachricht erwähnt Erstattung oder Rückgabe"},{"t":"msg","text":"Das tut mir leid, [Name]. Damit wir schnell helfen können, schick bitte deine Bestellnummer und sag mir, was schiefgelaufen ist."},{"t":"msg","text":"Schick bitte auch ein Foto des Artikels oder des Problems."},{"t":"cond","text":"Grund: beschädigt / falscher Artikel / Meinung geändert / sonstiges"},{"t":"tag","text":"Weiterleiten: beschädigt und falscher Artikel an das Qualitätsteam, Meinung geändert an das Retourenteam. Tag: erstattung-[Grund]"}],"es":[{"t":"trigger","text":"El mensaje menciona reembolso o devolución"},{"t":"msg","text":"Lo siento, [nombre]. Para ayudarte rápido, envíame tu número de pedido y cuéntame qué salió mal."},{"t":"msg","text":"Envía también una foto del artículo o del problema."},{"t":"cond","text":"Motivo: dañado / artículo equivocado / cambió de opinión / otro"},{"t":"tag","text":"Dirigir: dañado y artículo equivocado al equipo de calidad, cambió de opinión al equipo de devoluciones. Etiqueta: reembolso-[motivo]"}],"fr":[{"t":"trigger","text":"Le message mentionne un remboursement ou un retour"},{"t":"msg","text":"Désolé pour ça, [nom]. Pour t'aider vite, envoie-moi ton numéro de commande et dis-moi ce qui n'a pas marché."},{"t":"msg","text":"Envoie aussi une photo de l'article ou du problème."},{"t":"cond","text":"Motif : abîmé / mauvais article / changement d'avis / autre"},{"t":"tag","text":"Orienter : abîmé et mauvais article vers l'équipe qualité, changement d'avis vers l'équipe retours. Tag : remboursement-[motif]"}],"pt":[{"t":"trigger","text":"Mensagem menciona reembolso ou devolução"},{"t":"msg","text":"Sinto muito por isso, [nome]. Para ajudar rápido, me manda o número do pedido e conta o que deu errado."},{"t":"msg","text":"Manda também uma foto do item ou do problema."},{"t":"cond","text":"Motivo: danificado / item errado / mudou de ideia / outro"},{"t":"tag","text":"Encaminhar: danificado e item errado para a equipe de qualidade, mudou de ideia para a equipe de devoluções. Tag: reembolso-[motivo]"}]},"faq-deflection":{"en":[{"t":"trigger","text":"Message looks like a common question (hours, shipping, returns, payment)"},{"t":"cond","text":"Which topic: opening hours, shipping, returns, or payment?"},{"t":"msg","text":"Send the matching answer from your policy, e.g. \"We ship in [days]. Shipping costs [fee]. Details: [policy link].\""},{"t":"msg","text":"\"Did that answer your question? Reply NO and I will connect you with a person.\""}],"ar":[{"t":"trigger","text":"رسالة شكلها سؤال شائع (مواعيد، شحن، استرجاع، دفع)"},{"t":"cond","text":"أنهي موضوع: مواعيد العمل، الشحن، الاسترجاع، ولا الدفع؟"},{"t":"msg","text":"ابعت الإجابة المناسبة من سياستك، مثلًا \"بنشحن خلال [الأيام]. الشحن بـ [الرسوم]. التفاصيل: [لينك السياسة].\""},{"t":"msg","text":"\"الإجابة كانت كفاية؟ اكتب لأ وأوصلك بموظف.\""}],"de":[{"t":"trigger","text":"Nachricht sieht nach einer häufigen Frage aus (Öffnungszeiten, Versand, Rückgabe, Zahlung)"},{"t":"cond","text":"Welches Thema: Öffnungszeiten, Versand, Rückgabe oder Zahlung?"},{"t":"msg","text":"Die passende Antwort aus deinen Richtlinien schicken, z. B. „Wir versenden in [Tage] Tagen. Der Versand kostet [Gebühr]. Details: [Richtlinien-Link].“"},{"t":"msg","text":"„Hat das deine Frage beantwortet? Antworte NEIN und ich verbinde dich mit einem Menschen.“"}],"es":[{"t":"trigger","text":"El mensaje parece una pregunta frecuente (horarios, envío, devoluciones, pago)"},{"t":"cond","text":"¿Qué tema: horarios, envío, devoluciones o pago?"},{"t":"msg","text":"Enviar la respuesta correspondiente de tu política, p. ej. «Enviamos en [días] días. El envío cuesta [tarifa]. Detalles: [enlace de política].»"},{"t":"msg","text":"«¿Eso respondió tu pregunta? Responde NO y te conecto con una persona.»"}],"fr":[{"t":"trigger","text":"Le message ressemble à une question fréquente (horaires, livraison, retours, paiement)"},{"t":"cond","text":"Quel sujet : horaires, livraison, retours ou paiement ?"},{"t":"msg","text":"Envoyer la réponse correspondante de ta politique, p. ex. « Nous expédions en [jours] jours. La livraison coûte [tarif]. Détails : [lien de la politique]. »"},{"t":"msg","text":"« Cela a-t-il répondu à ta question ? Réponds NON et je te mets en relation avec une personne. »"}],"pt":[{"t":"trigger","text":"Mensagem parece uma pergunta frequente (horários, envio, devoluções, pagamento)"},{"t":"cond","text":"Qual o tema: horários, envio, devoluções ou pagamento?"},{"t":"msg","text":"Enviar a resposta correspondente da sua política, ex.: «Enviamos em [dias] dias. O envio custa [taxa]. Detalhes: [link da política].»"},{"t":"msg","text":"«Isso respondeu sua pergunta? Responde NÃO que eu te conecto com uma pessoa.»"}]},"angry-customer-de-escalation":{"en":[{"t":"trigger","text":"Message with strong negative words or several complaints"},{"t":"msg","text":"I am really sorry about this, [name]. You are right to expect better."},{"t":"msg","text":"Here is what I can do right now: [fix, e.g. replacement, refund, or call back today]."},{"t":"tag","text":"Hand over to a senior agent with a summary of the issue and what was offered. Tag: escalated"}],"ar":[{"t":"trigger","text":"رسالة فيها كلمات سلبية قوية أو شكاوى متكررة"},{"t":"msg","text":"أنا آسف فعلًا يا [الاسم]. من حقك تتوقع أحسن من كده."},{"t":"msg","text":"ده اللي أقدر أعمله دلوقتي: [الحل، مثل استبدال أو استرجاع أو مكالمة اليوم]."},{"t":"tag","text":"سلّم لموظف أقدم مع ملخص المشكلة والعرض المقدم. وسم: متصعّد"}],"de":[{"t":"trigger","text":"Nachricht mit stark negativen Worten oder mehreren Beschwerden"},{"t":"msg","text":"Es tut mir wirklich leid, [Name]. Du darfst zu Recht Besseres erwarten."},{"t":"msg","text":"Das kann ich sofort tun: [Lösung, z. B. Ersatz, Erstattung oder Rückruf noch heute]."},{"t":"tag","text":"An einen erfahrenen Mitarbeiter übergeben, mit Zusammenfassung des Problems und des Angebots. Tag: eskaliert"}],"es":[{"t":"trigger","text":"Mensaje con palabras muy negativas o varias quejas"},{"t":"msg","text":"Lo siento muchísimo, [nombre]. Tienes derecho a esperar algo mejor."},{"t":"msg","text":"Esto es lo que puedo hacer ahora mismo: [solución, p. ej. reemplazo, reembolso o llamada hoy mismo]."},{"t":"tag","text":"Pasar a un agente senior con un resumen del problema y de lo ofrecido. Etiqueta: escalado"}],"fr":[{"t":"trigger","text":"Message avec des mots très négatifs ou plusieurs plaintes"},{"t":"msg","text":"Je suis vraiment désolé, [nom]. Tu es en droit d'attendre mieux."},{"t":"msg","text":"Voici ce que je peux faire tout de suite : [solution, p. ex. remplacement, remboursement ou rappel aujourd'hui]."},{"t":"tag","text":"Transférer à un agent senior avec un résumé du problème et de ce qui a été proposé. Tag : escaladé"}],"pt":[{"t":"trigger","text":"Mensagem com palavras muito negativas ou várias reclamações"},{"t":"msg","text":"Sinto muito mesmo por isso, [nome]. Você tem razão em esperar mais."},{"t":"msg","text":"Isso é o que posso fazer agora: [solução, ex.: troca, reembolso ou retorno de ligação hoje]."},{"t":"tag","text":"Transferir para um atendente sênior com resumo do problema e do que foi oferecido. Tag: escalado"}]},"shipping-status-lookup":{"en":[{"t":"trigger","text":"Message asks \"where is my order\" or \"tracking\""},{"t":"msg","text":"Hi [name]! Please send your order number or the phone number used on the order."},{"t":"msg","text":"Order #[order] is [status] with [courier]. Expected delivery: [ETA]. Tracking: [tracking link]."}],"ar":[{"t":"trigger","text":"رسالة بتسأل \"فين طلبي\" أو \"تتبع\""},{"t":"msg","text":"أهلاً [الاسم]! ابعت رقم الطلب أو رقم التليفون المستخدم في الطلب."},{"t":"msg","text":"طلب رقم [رقم الطلب] [الحالة] مع [شركة الشحن]. التسليم المتوقع: [الموعد]. التتبع: [لينك التتبع]."}],"de":[{"t":"trigger","text":"Nachricht fragt „wo ist meine Bestellung“ oder „Sendungsverfolgung“"},{"t":"msg","text":"Hallo [Name]! Schick mir bitte deine Bestellnummer oder die Telefonnummer aus der Bestellung."},{"t":"msg","text":"Bestellung #[Bestellnummer] ist [Status] mit [Kurier]. Voraussichtliche Zustellung: [ETA]. Verfolgung: [Tracking-Link]."}],"es":[{"t":"trigger","text":"El mensaje pregunta «dónde está mi pedido» o «seguimiento»"},{"t":"msg","text":"¡Hola [nombre]! Envíame tu número de pedido o el teléfono usado en el pedido."},{"t":"msg","text":"El pedido #[pedido] está [estado] con [courier]. Entrega estimada: [ETA]. Seguimiento: [enlace de seguimiento]."}],"fr":[{"t":"trigger","text":"Le message demande « où est ma commande » ou « suivi »"},{"t":"msg","text":"Bonjour [nom] ! Envoie-moi ton numéro de commande ou le numéro de téléphone utilisé pour la commande."},{"t":"msg","text":"La commande n°[commande] est [statut] avec [transporteur]. Livraison prévue : [ETA]. Suivi : [lien de suivi]."}],"pt":[{"t":"trigger","text":"Mensagem pergunta «onde está meu pedido» ou «rastreio»"},{"t":"msg","text":"Olá [nome]! Me manda o número do pedido ou o telefone usado no pedido."},{"t":"msg","text":"O pedido #[pedido] está [status] com [transportadora]. Previsão de entrega: [ETA]. Rastreio: [link de rastreio]."}]},"warranty-claim":{"en":[{"t":"trigger","text":"Message mentions warranty or a faulty product"},{"t":"msg","text":"Sorry to hear that, [name]. Let us check your warranty. What is your order number and the purchase date?"},{"t":"msg","text":"Please describe the problem and send a short photo or video of it."},{"t":"cond","text":"Is the purchase date within the warranty period ([months] months)?"},{"t":"msg","text":"Yes: \"Your item is covered. A teammate will confirm the next step (repair, replacement) within [time].\" No: \"It looks outside the warranty. A teammate will review your options.\""},{"t":"tag","text":"Tag: warranty-claim, with the order number saved in the chat notes"}],"ar":[{"t":"trigger","text":"رسالة فيها ضمان أو منتج معطّل"},{"t":"msg","text":"آسفين لده يا [الاسم]. خلينا نراجع الضمان. إيه رقم الطلب وتاريخ الشراء؟"},{"t":"msg","text":"وصّف المشكلة وابعت صورة أو فيديو قصير ليها."},{"t":"cond","text":"هل تاريخ الشراء داخل مدة الضمان ([عدد] شهر)؟"},{"t":"msg","text":"أيوه: \"منتجك مغطّى. زميل هيأكد الخطوة الجاية (إصلاح أو استبدال) خلال [المدة].\" لأ: \"شكله خارج الضمان. زميل هيراجع الخيارات المتاحة.\""},{"t":"tag","text":"وسم: طلب-ضمان، مع حفظ رقم الطلب في ملاحظات المحادثة"}],"de":[{"t":"trigger","text":"Nachricht erwähnt Garantie oder ein defektes Produkt"},{"t":"msg","text":"Das tut mir leid, [Name]. Lass uns deine Garantie prüfen. Wie lautet deine Bestellnummer und das Kaufdatum?"},{"t":"msg","text":"Beschreibe bitte das Problem und schick ein kurzes Foto oder Video davon."},{"t":"cond","text":"Liegt das Kaufdatum innerhalb der Garantiezeit ([Monate] Monate)?"},{"t":"msg","text":"Ja: „Dein Artikel ist abgedeckt. Ein Mitarbeiter bestätigt den nächsten Schritt (Reparatur, Ersatz) innerhalb von [Zeit].“ Nein: „Es liegt wohl außerhalb der Garantie. Ein Mitarbeiter prüft deine Optionen.“"},{"t":"tag","text":"Tag: garantiefall, Bestellnummer in den Chat-Notizen speichern"}],"es":[{"t":"trigger","text":"El mensaje menciona garantía o un producto defectuoso"},{"t":"msg","text":"Lamento escuchar eso, [nombre]. Vamos a revisar tu garantía. ¿Cuál es tu número de pedido y la fecha de compra?"},{"t":"msg","text":"Describe el problema y envía una foto o video corto del mismo."},{"t":"cond","text":"¿La fecha de compra está dentro del período de garantía ([meses] meses)?"},{"t":"msg","text":"Sí: «Tu artículo está cubierto. Un compañero confirmará el siguiente paso (reparación, reemplazo) en [tiempo].» No: «Parece fuera de garantía. Un compañero revisará tus opciones.»"},{"t":"tag","text":"Etiqueta: reclamo-garantía, con el número de pedido guardado en las notas del chat"}],"fr":[{"t":"trigger","text":"Le message mentionne la garantie ou un produit défectueux"},{"t":"msg","text":"Désolé d'entendre ça, [nom]. Vérifions ta garantie. Quel est ton numéro de commande et la date d'achat ?"},{"t":"msg","text":"Décris le problème et envoie une petite photo ou vidéo."},{"t":"cond","text":"La date d'achat est-elle dans la période de garantie ([mois] mois) ?"},{"t":"msg","text":"Oui : « Ton article est couvert. Un collègue confirmera la prochaine étape (réparation, remplacement) sous [délai]. » Non : « Cela semble hors garantie. Un collègue examinera tes options. »"},{"t":"tag","text":"Tag : réclamation-garantie, avec le numéro de commande enregistré dans les notes de la conversation"}],"pt":[{"t":"trigger","text":"Mensagem menciona garantia ou produto com defeito"},{"t":"msg","text":"Sinto muito por isso, [nome]. Vamos verificar sua garantia. Qual é o número do pedido e a data da compra?"},{"t":"msg","text":"Descreva o problema e mande uma foto ou vídeo curto dele."},{"t":"cond","text":"A data da compra está dentro do período de garantia ([meses] meses)?"},{"t":"msg","text":"Sim: «Seu item está coberto. Um colega confirmará o próximo passo (reparo, troca) em [tempo].» Não: «Parece fora da garantia. Um colega vai analisar suas opções.»"},{"t":"tag","text":"Tag: reclamação-garantia, com o número do pedido salvo nas notas da conversa"}]},"lead-magnet-delivery":{"en":[{"t":"trigger","text":"Comment contains the keyword \"GUIDE\""},{"t":"msg","text":"(Public reply) Sent! Check your DMs, [name]."},{"t":"msg","text":"Hi [name]! Here is your free [guide/template]: [download link]. I would also love to send you tips now and then. Reply \"YES\" to get them, or ignore this to skip."},{"t":"tag","text":"Tag: lead-magnet-[name]; if \"YES\", add to the tips sequence"}],"ar":[{"t":"trigger","text":"تعليق فيه كلمة \"دليل\""},{"t":"msg","text":"(رد علني) اتبعت! بصّ على الخاص يا [الاسم]."},{"t":"msg","text":"أهلاً [الاسم]! ده [الدليل/القالب] المجاني: [لينك التحميل]. وممكن أبعتلك نصايح من وقت لتاني. اكتب \"أيوه\" لو عايز، أو تجاهل الرسالة لو لأ."},{"t":"tag","text":"وسم: ملف-مجاني-[الاسم]؛ لو \"أيوه\" أضفه لتسلسل النصايح"}],"de":[{"t":"trigger","text":"Kommentar enthält das Schlüsselwort „GUIDE“"},{"t":"msg","text":"(Öffentliche Antwort) Geschickt! Schau in deine DMs, [Name]."},{"t":"msg","text":"Hallo [Name]! Hier ist dein kostenloser [Guide/Vorlage]: [Download-Link]. Ich würde dir auch gern ab und zu Tipps schicken. Antworte „JA“, um sie zu bekommen, oder ignoriere das einfach."},{"t":"tag","text":"Tag: leadmagnet-[Name]; bei „JA“ in die Tipps-Sequenz aufnehmen"}],"es":[{"t":"trigger","text":"Comentario contiene la palabra clave «GUÍA»"},{"t":"msg","text":"(Respuesta pública) ¡Enviado! Revisa tus DMs, [nombre]."},{"t":"msg","text":"¡Hola [nombre]! Aquí está tu [guía/plantilla] gratis: [enlace de descarga]. También me encantaría enviarte consejos de vez en cuando. Responde «SÍ» para recibirlos, o ignora esto para omitir."},{"t":"tag","text":"Etiqueta: leadmagnet-[nombre]; si «SÍ», añadir a la secuencia de consejos"}],"fr":[{"t":"trigger","text":"Commentaire contenant le mot-clé « GUIDE »"},{"t":"msg","text":"(Réponse publique) Envoyé ! Regarde tes DM, [nom]."},{"t":"msg","text":"Bonjour [nom] ! Voici ton [guide/modèle] gratuit : [lien de téléchargement]. J'aimerais aussi t'envoyer des conseils de temps en temps. Réponds « OUI » pour les recevoir, ou ignore ce message."},{"t":"tag","text":"Tag : leadmagnet-[nom] ; si « OUI », ajouter à la séquence de conseils"}],"pt":[{"t":"trigger","text":"Comentário contém a palavra-chave «GUIA»"},{"t":"msg","text":"(Resposta pública) Enviado! Olha suas DMs, [nome]."},{"t":"msg","text":"Olá [nome]! Aqui está seu [guia/modelo] grátis: [link de download]. Também adoraria te mandar dicas de vez em quando. Responde «SIM» para receber, ou ignora essa mensagem."},{"t":"tag","text":"Tag: isca-[nome]; se «SIM», adicionar à sequência de dicas"}]},"webinar-registration":{"en":[{"t":"trigger","text":"DM contains \"WEBINAR\""},{"t":"msg","text":"Great, [name]! The webinar \"[title]\" is on [date] at [time]. Reply with your email to register."},{"t":"msg","text":"You are registered! Add it to your calendar: [calendar link]. Join link: [webinar link]."},{"t":"msg","text":"Starting in 1 hour: join here: [webinar link]. See you soon, [name]!"},{"t":"tag","text":"Tag: webinar-registered-[date]"}],"ar":[{"t":"trigger","text":"رسالة فيها \"ندوة\""},{"t":"msg","text":"تمام يا [الاسم]! ندوة \"[العنوان]\" يوم [التاريخ] الساعة [الوقت]. ابعت إيميلك للتسجيل."},{"t":"msg","text":"اتسجلت! أضفها لتقويمك: [لينك التقويم]. لينك الدخول: [لينك الندوة]."},{"t":"msg","text":"بتبدأ بعد ساعة: ادخل من هنا: [لينك الندوة]. نشوفك قريب يا [الاسم]!"},{"t":"tag","text":"وسم: مسجل-ندوة-[التاريخ]"}],"de":[{"t":"trigger","text":"DM enthält „WEBINAR“"},{"t":"msg","text":"Super, [Name]! Das Webinar „[Titel]“ ist am [Datum] um [Uhrzeit]. Antworte mit deiner E-Mail zur Anmeldung."},{"t":"msg","text":"Du bist angemeldet! Trag es in deinen Kalender ein: [Kalenderlink]. Teilnahme-Link: [Webinar-Link]."},{"t":"msg","text":"Es geht in 1 Stunde los: hier beitreten: [Webinar-Link]. Bis gleich, [Name]!"},{"t":"tag","text":"Tag: webinar-angemeldet-[Datum]"}],"es":[{"t":"trigger","text":"DM contiene «WEBINAR»"},{"t":"msg","text":"¡Genial, [nombre]! El webinar «[título]» es el [fecha] a las [hora]. Responde con tu email para registrarte."},{"t":"msg","text":"¡Ya estás registrado! Añádelo a tu calendario: [enlace de calendario]. Enlace para unirte: [enlace del webinar]."},{"t":"msg","text":"Empieza en 1 hora: únete aquí: [enlace del webinar]. ¡Hasta pronto, [nombre]!"},{"t":"tag","text":"Etiqueta: webinar-registrado-[fecha]"}],"fr":[{"t":"trigger","text":"DM contient « WEBINAIRE »"},{"t":"msg","text":"Super, [nom] ! Le webinaire « [titre] » a lieu le [date] à [heure]. Réponds avec ton e-mail pour t'inscrire."},{"t":"msg","text":"Tu es inscrit ! Ajoute-le à ton calendrier : [lien du calendrier]. Lien pour rejoindre : [lien du webinaire]."},{"t":"msg","text":"Ça commence dans 1 heure : rejoins ici : [lien du webinaire]. À tout de suite, [nom] !"},{"t":"tag","text":"Tag : webinaire-inscrit-[date]"}],"pt":[{"t":"trigger","text":"DM contém «WEBINAR»"},{"t":"msg","text":"Ótimo, [nome]! O webinar «[título]» é em [data] às [hora]. Responde com seu e-mail para se inscrever."},{"t":"msg","text":"Você está inscrito! Adiciona ao seu calendário: [link do calendário]. Link para entrar: [link do webinar]."},{"t":"msg","text":"Começa em 1 hora: entre aqui: [link do webinar]. Até já, [nome]!"},{"t":"tag","text":"Tag: webinar-inscrito-[data]"}]},"quiz-to-qualify":{"en":[{"t":"trigger","text":"DM contains \"start\" or the quiz keyword"},{"t":"msg","text":"Q1: How soon do you want to start? A) This week B) This month C) Just looking"},{"t":"msg","text":"Q2: What is your budget? A) Over [Y] B) [X] to [Y] C) Under [X]"},{"t":"msg","text":"Q3: Who decides? A) Me B) Me and a partner C) Someone else"},{"t":"cond","text":"Score: A=2, B=1, C=0 per answer. Total 5 or more is a hot lead"},{"t":"tag","text":"Hot lead: tag hot-lead and hand to a human now. Others: tag nurture and send the guide link"}],"ar":[{"t":"trigger","text":"رسالة فيها \"ابدأ\" أو كلمة الكويز"},{"t":"msg","text":"س1: امتى عايز تبدأ؟ أ) الأسبوع ده ب) الشهر ده ج) بتفرج بس"},{"t":"msg","text":"س2: ميزانيتك كام؟ أ) أكتر من [Y] ب) من [X] لـ [Y] ج) أقل من [X]"},{"t":"msg","text":"س3: مين بياخد القرار؟ أ) أنا ب) أنا وشريك ج) حد تاني"},{"t":"cond","text":"احسب: أ=2، ب=1، ج=0 لكل إجابة. المجموع 5 أو أكتر يعني عميل ساخن"},{"t":"tag","text":"ساخن: وسم عميل-ساخن وحوّل لموظف فورًا. غيره: وسم متابعة وابعت لينك الدليل"}],"de":[{"t":"trigger","text":"DM enthält „start“ oder das Quiz-Schlüsselwort"},{"t":"msg","text":"F1: Wie bald möchtest du starten? A) Diese Woche B) Diesen Monat C) Schaue mich nur um"},{"t":"msg","text":"F2: Wie hoch ist dein Budget? A) Über [Y] B) [X] bis [Y] C) Unter [X]"},{"t":"msg","text":"F3: Wer entscheidet? A) Ich B) Ich und ein Partner C) Jemand anderes"},{"t":"cond","text":"Punkte: A=2, B=1, C=0 pro Antwort. Ab 5 Punkten ist es ein heißer Lead"},{"t":"tag","text":"Heißer Lead: Tag heiss-lead und sofort an einen Menschen übergeben. Andere: Tag pflegen und den Guide-Link schicken"}],"es":[{"t":"trigger","text":"DM contiene «empezar» o la palabra clave del quiz"},{"t":"msg","text":"P1: ¿Cuándo quieres empezar? A) Esta semana B) Este mes C) Solo estoy mirando"},{"t":"msg","text":"P2: ¿Cuál es tu presupuesto? A) Más de [Y] B) De [X] a [Y] C) Menos de [X]"},{"t":"msg","text":"P3: ¿Quién decide? A) Yo B) Yo y mi pareja C) Otra persona"},{"t":"cond","text":"Puntuación: A=2, B=1, C=0 por respuesta. Total de 5 o más es un lead caliente"},{"t":"tag","text":"Lead caliente: etiqueta lead-caliente y pasar a un humano ahora. Demás: etiqueta nutrir y enviar el enlace de la guía"}],"fr":[{"t":"trigger","text":"DM contient « démarrer » ou le mot-clé du quiz"},{"t":"msg","text":"Q1 : Quand veux-tu commencer ? A) Cette semaine B) Ce mois-ci C) Je regarde juste"},{"t":"msg","text":"Q2 : Quel est ton budget ? A) Plus de [Y] B) De [X] à [Y] C) Moins de [X]"},{"t":"msg","text":"Q3 : Qui décide ? A) Moi B) Moi et un partenaire C) Quelqu'un d'autre"},{"t":"cond","text":"Score : A=2, B=1, C=0 par réponse. Un total de 5 ou plus est un prospect chaud"},{"t":"tag","text":"Prospect chaud : tag prospect-chaud et transmettre à un humain maintenant. Autres : tag nurturing et envoyer le lien du guide"}],"pt":[{"t":"trigger","text":"DM contém «começar» ou a palavra-chave do quiz"},{"t":"msg","text":"P1: Quando você quer começar? A) Esta semana B) Este mês C) Só estou olhando"},{"t":"msg","text":"P2: Qual é seu orçamento? A) Mais de [Y] B) De [X] a [Y] C) Menos de [X]"},{"t":"msg","text":"P3: Quem decide? A) Eu B) Eu e um parceiro C) Outra pessoa"},{"t":"cond","text":"Pontuação: A=2, B=1, C=0 por resposta. Total 5 ou mais é um lead quente"},{"t":"tag","text":"Lead quente: tag lead-quente e passar para um humano agora. Demais: tag nutrir e enviar o link do guia"}]},"real-estate-enquiry":{"en":[{"t":"trigger","text":"DM or ad reply about a property"},{"t":"msg","text":"Hi [name]! Thanks for your interest in [property]. Which area are you looking in, and is it to buy or rent?"},{"t":"msg","text":"What is your budget range?"},{"t":"msg","text":"When are you planning to move or buy?"},{"t":"cond","text":"Does the request match an available listing?"},{"t":"msg","text":"Yes: \"I found [number] options. Would you like to book a viewing? Pick a time: [calendar link].\" No: \"I will keep your details and tell you when something fits.\""}],"ar":[{"t":"trigger","text":"رسالة أو رد على إعلان عن عقار"},{"t":"msg","text":"أهلاً [الاسم]! شكرًا لاهتمامك بـ [العقار]. بتدوّر في أنهي منطقة، وللشراء ولا للإيجار؟"},{"t":"msg","text":"ميزانيتك تقريبًا كام؟"},{"t":"msg","text":"امتى بتخطط تنتقل أو تشتري؟"},{"t":"cond","text":"هل الطلب بيطابق عقار متاح؟"},{"t":"msg","text":"أيوه: \"لقيت [عدد] خيارات. تحب تحجز معاينة؟ اختار ميعاد: [لينك التقويم].\" لأ: \"هحتفظ ببياناتك وأبلغك لما يظهر حاجة مناسبة.\""}],"de":[{"t":"trigger","text":"DM oder Anzeigen-Antwort zu einer Immobilie"},{"t":"msg","text":"Hallo [Name]! Danke für dein Interesse an [Immobilie]. In welcher Gegend suchst du, und geht es um Kauf oder Miete?"},{"t":"msg","text":"In welchem Budgetrahmen bewegst du dich?"},{"t":"msg","text":"Wann planst du den Umzug oder Kauf?"},{"t":"cond","text":"Passt die Anfrage zu einem verfügbaren Angebot?"},{"t":"msg","text":"Ja: „Ich habe [Anzahl] Optionen gefunden. Möchtest du eine Besichtigung buchen? Such dir einen Termin: [Kalenderlink].“ Nein: „Ich speichere deine Daten und melde mich, sobald etwas passt.\""}],"es":[{"t":"trigger","text":"DM o respuesta a anuncio sobre una propiedad"},{"t":"msg","text":"¡Hola [nombre]! Gracias por tu interés en [propiedad]. ¿En qué zona buscas, y es para comprar o alquilar?"},{"t":"msg","text":"¿Cuál es tu rango de presupuesto?"},{"t":"msg","text":"¿Cuándo planeas mudarte o comprar?"},{"t":"cond","text":"¿La solicitud coincide con un anuncio disponible?"},{"t":"msg","text":"Sí: «Encontré [número] opciones. ¿Quieres reservar una visita? Elige hora: [enlace de calendario].» No: «Guardaré tus datos y te avisaré cuando haya algo adecuado.»"}],"fr":[{"t":"trigger","text":"DM ou réponse à une annonce au sujet d'un bien"},{"t":"msg","text":"Bonjour [nom] ! Merci de ton intérêt pour [bien]. Dans quel secteur cherches-tu, et est-ce pour acheter ou louer ?"},{"t":"msg","text":"Quelle est ta fourchette de budget ?"},{"t":"msg","text":"Quand prévois-tu de déménager ou d'acheter ?"},{"t":"cond","text":"La demande correspond-elle à une annonce disponible ?"},{"t":"msg","text":"Oui : « J'ai trouvé [nombre] options. Souhaites-tu réserver une visite ? Choisis un créneau : [lien du calendrier]. » Non : « Je garde tes coordonnées et te préviens dès que quelque chose convient. »"}],"pt":[{"t":"trigger","text":"DM ou resposta de anúncio sobre um imóvel"},{"t":"msg","text":"Olá [nome]! Obrigado pelo interesse em [imóvel]. Em qual região você procura, e é para comprar ou alugar?"},{"t":"msg","text":"Qual é sua faixa de orçamento?"},{"t":"msg","text":"Quando você planeja se mudar ou comprar?"},{"t":"cond","text":"A solicitação corresponde a um anúncio disponível?"},{"t":"msg","text":"Sim: «Encontrei [número] opções. Quer agendar uma visita? Escolhe um horário: [link do calendário].» Não: «Vou guardar seus dados e te avisar quando aparecer algo adequado.»"}]},"clinic-intake":{"en":[{"t":"trigger","text":"Message asking to book or enquire at the clinic"},{"t":"msg","text":"Hello [name], welcome to [clinic]. Is this your first visit, or are you an existing patient?"},{"t":"msg","text":"Which service do you need (check-up, follow-up, other)? Please do not send medical details here."},{"t":"msg","text":"What is your preferred day and time?"},{"t":"msg","text":"Your full name and phone number, please."},{"t":"cond","text":"Is this an emergency? If yes, tell them to call emergency services or the clinic phone directly."},{"t":"tag","text":"Pass to reception for confirmation. Tag: clinic-request. Review privacy rules before real use"}],"ar":[{"t":"trigger","text":"رسالة بتطلب حجز أو استفسار في العيادة"},{"t":"msg","text":"أهلاً [الاسم]، مرحبًا بيك في [العيادة]. دي أول زيارة ولا مريض سابق؟"},{"t":"msg","text":"أنهي خدمة محتاجها (كشف، متابعة، غيره)؟ من فضلك متبعتش تفاصيل طبية هنا."},{"t":"msg","text":"إيه اليوم والوقت المناسبين ليك؟"},{"t":"msg","text":"اسمك الكامل ورقم تليفونك لو سمحت."},{"t":"cond","text":"هل دي حالة طوارئ؟ لو أيوه قولّه يتصل بالإسعاف أو بتليفون العيادة مباشرة."},{"t":"tag","text":"سلّم للاستقبال للتأكيد. وسم: طلب-عيادة. راجع قواعد الخصوصية قبل الاستخدام الفعلي"}],"de":[{"t":"trigger","text":"Nachricht mit Terminwunsch oder Anfrage an die Klinik"},{"t":"msg","text":"Hallo [Name], willkommen bei [Klinik]. Ist das dein erster Besuch, oder bist du bereits Patient bei uns?"},{"t":"msg","text":"Welche Leistung brauchst du (Kontrolle, Nachsorge, sonstiges)? Bitte schick hier keine medizinischen Details."},{"t":"msg","text":"Welcher Tag und welche Uhrzeit passen dir am besten?"},{"t":"msg","text":"Bitte noch deinen vollständigen Namen und deine Telefonnummer."},{"t":"cond","text":"Ist es ein Notfall? Falls ja, bitte direkt den Notruf oder die Klinik-Telefonnummer nennen."},{"t":"tag","text":"Zur Bestätigung an die Rezeption geben. Tag: klinik-anfrage. Datenschutzregeln vor echtem Einsatz prüfen"}],"es":[{"t":"trigger","text":"Mensaje pidiendo cita o información en la clínica"},{"t":"msg","text":"Hola [nombre], bienvenido a [clínica]. ¿Es tu primera visita o ya eres paciente?"},{"t":"msg","text":"¿Qué servicio necesitas (revisión, seguimiento, otro)? Por favor no envíes datos médicos aquí."},{"t":"msg","text":"¿Qué día y hora prefieres?"},{"t":"msg","text":"Tu nombre completo y número de teléfono, por favor."},{"t":"cond","text":"¿Es una emergencia? Si sí, indicar que llamen a emergencias o al teléfono de la clínica directamente."},{"t":"tag","text":"Pasar a recepción para confirmación. Etiqueta: solicitud-clínica. Revisar las reglas de privacidad antes del uso real"}],"fr":[{"t":"trigger","text":"Message demandant un rendez-vous ou un renseignement à la clinique"},{"t":"msg","text":"Bonjour [nom], bienvenue à [clinique]. Est-ce ta première visite, ou es-tu déjà patient ?"},{"t":"msg","text":"Quel service te faut-il (contrôle, suivi, autre) ? Merci de ne pas envoyer de détails médicaux ici."},{"t":"msg","text":"Quel jour et quelle heure préfères-tu ?"},{"t":"msg","text":"Ton nom complet et ton numéro de téléphone, s'il te plaît."},{"t":"cond","text":"Est-ce une urgence ? Si oui, indiquer d'appeler les urgences ou le téléphone de la clinique directement."},{"t":"tag","text":"Transmettre à la réception pour confirmation. Tag : demande-clinique. Vérifier les règles de confidentialité avant usage réel"}],"pt":[{"t":"trigger","text":"Mensagem pedindo consulta ou informação na clínica"},{"t":"msg","text":"Olá [nome], bem-vindo à [clínica]. É sua primeira visita ou você já é paciente?"},{"t":"msg","text":"De qual serviço você precisa (check-up, retorno, outro)? Por favor não envie detalhes médicos aqui."},{"t":"msg","text":"Qual dia e horário você prefere?"},{"t":"msg","text":"Seu nome completo e telefone, por favor."},{"t":"cond","text":"É uma emergência? Se sim, orientar a ligar para emergência ou para o telefone da clínica diretamente."},{"t":"tag","text":"Passar para a recepção para confirmação. Tag: solicitação-clínica. Revisar regras de privacidade antes do uso real"}]},"agency-audit-request":{"en":[{"t":"trigger","text":"DM contains \"audit\" or \"growth\""},{"t":"msg","text":"Hi [name]! We run a free 20-minute audit. What is your business and website or Instagram handle?"},{"t":"msg","text":"Roughly how much do you spend on ads per month? A) Under [X] B) [X] to [Y] C) Over [Y]"},{"t":"msg","text":"Yes: \"Great fit. Book your 20-minute audit here: [calendar link].\" No: \"Thanks! Here is a free guide for now: [guide link].\""},{"t":"tag","text":"Tag: audit-booked or audit-guide"}],"ar":[{"t":"trigger","text":"رسالة فيها \"تدقيق\" أو \"نمو\""},{"t":"msg","text":"أهلاً [الاسم]! بنعمل تدقيق مجاني 20 دقيقة. إيه نشاطك وموقعك أو حساب إنستجرام؟"},{"t":"msg","text":"تقريبًا بتصرف كام على الإعلانات في الشهر؟ أ) أقل من [X] ب) من [X] لـ [Y] ج) أكتر من [Y]"},{"t":"msg","text":"أيوه: \"مناسب جدًا. احجز التدقيق 20 دقيقة من هنا: [لينك التقويم].\" لأ: \"شكرًا! ده دليل مجاني دلوقتي: [لينك الدليل].\""},{"t":"tag","text":"وسم: تدقيق-محجوز أو دليل-تدقيق"}],"de":[{"t":"trigger","text":"DM enthält „Audit“ oder „Wachstum“"},{"t":"msg","text":"Hallo [Name]! Wir bieten ein kostenloses 20-minütiges Audit. Was ist dein Geschäft und deine Website oder dein Instagram-Handle?"},{"t":"msg","text":"Wie viel gibst du ungefähr pro Monat für Werbung aus? A) Unter [X] B) [X] bis [Y] C) Über [Y]"},{"t":"msg","text":"Ja: „Passt super. Buche dein 20-minütiges Audit hier: [Kalenderlink].“ Nein: „Danke! Hier erstmal ein kostenloser Guide: [Guide-Link].\""},{"t":"tag","text":"Tag: audit-gebucht oder audit-guide"}],"es":[{"t":"trigger","text":"DM contiene «auditoría» o «crecimiento»"},{"t":"msg","text":"¡Hola [nombre]! Hacemos una auditoría gratuita de 20 minutos. ¿Cuál es tu negocio y tu web o usuario de Instagram?"},{"t":"msg","text":"¿Cuánto gastas aproximadamente en anuncios al mes? A) Menos de [X] B) De [X] a [Y] C) Más de [Y]"},{"t":"msg","text":"Sí: «Perfecto. Reserva tu auditoría de 20 minutos aquí: [enlace de calendario].» No: «¡Gracias! Aquí tienes una guía gratuita por ahora: [enlace de guía].»"},{"t":"tag","text":"Etiqueta: auditoría-reservada o auditoría-guía"}],"fr":[{"t":"trigger","text":"DM contient « audit » ou « croissance »"},{"t":"msg","text":"Bonjour [nom] ! Nous offrons un audit gratuit de 20 minutes. Quelle est ton activité et ton site ou ton pseudo Instagram ?"},{"t":"msg","text":"Combien dépenses-tu environ en publicité par mois ? A) Moins de [X] B) De [X] à [Y] C) Plus de [Y]"},{"t":"msg","text":"Oui : « Parfait. Réserve ton audit de 20 minutes ici : [lien du calendrier]. » Non : « Merci ! Voici un guide gratuit pour commencer : [lien du guide]. »"},{"t":"tag","text":"Tag : audit-réservé ou audit-guide"}],"pt":[{"t":"trigger","text":"DM contém «auditoria» ou «crescimento»"},{"t":"msg","text":"Olá [nome]! Fazemos uma auditoria gratuita de 20 minutos. Qual é seu negócio e seu site ou perfil do Instagram?"},{"t":"msg","text":"Quanto você gasta por mês em anúncios, aproximadamente? A) Menos de [X] B) De [X] a [Y] C) Mais de [Y]"},{"t":"msg","text":"Sim: «Perfeito. Agende sua auditoria de 20 minutos aqui: [link do calendário].» Não: «Obrigado! Aqui vai um guia gratuito por enquanto: [link do guia].»"},{"t":"tag","text":"Tag: auditoria-agendada ou auditoria-guia"}]},"newsletter-opt-in-from-dm":{"en":[{"t":"trigger","text":"DM contains \"newsletter\" or \"updates\""},{"t":"msg","text":"Happy to send you our newsletter, [name]. We will email [what, how often]. Reply \"YES\" to agree to receive it. You can unsubscribe anytime."},{"t":"tag","text":"Save the email and the time of consent. Tag: newsletter-consent"}],"ar":[{"t":"trigger","text":"رسالة فيها \"نشرة\" أو \"جديد\""},{"t":"msg","text":"يسعدنا نبعتلك نشرتنا يا [الاسم]. هنبعت إيميل [إيه، كل قد إيه]. اكتب \"أيوه\" عشان توافق على استلامها. وتقدر تلغي في أي وقت."},{"t":"tag","text":"احفظ الإيميل ووقت الموافقة. وسم: موافقة-نشرة"}],"de":[{"t":"trigger","text":"DM enthält „Newsletter“ oder „Updates“"},{"t":"msg","text":"Gern schicke ich dir unseren Newsletter, [Name]. Wir mailen [was, wie oft]. Antworte „JA“, um ihn zu erhalten. Abmeldung jederzeit möglich."},{"t":"tag","text":"E-Mail und Zeitpunkt der Zustimmung speichern. Tag: newsletter-zustimmung"}],"es":[{"t":"trigger","text":"DM contiene «newsletter» o «novedades»"},{"t":"msg","text":"Encantado de enviarte nuestro boletín, [nombre]. Enviaremos [qué, con qué frecuencia]. Responde «SÍ» para aceptar recibirlo. Puedes darte de baja cuando quieras."},{"t":"tag","text":"Guardar el email y la hora del consentimiento. Etiqueta: consentimiento-newsletter"}],"fr":[{"t":"trigger","text":"DM contient « newsletter » ou « actualités »"},{"t":"msg","text":"Avec plaisir pour notre newsletter, [nom]. Nous envoyons [quoi, à quelle fréquence]. Réponds « OUI » pour accepter de la recevoir. Désinscription possible à tout moment."},{"t":"tag","text":"Enregistrer l'e-mail et l'heure du consentement. Tag : consentement-newsletter"}],"pt":[{"t":"trigger","text":"DM contém «newsletter» ou «novidades»"},{"t":"msg","text":"Com prazer te envio nossa newsletter, [nome]. Vamos mandar [o quê, com que frequência]. Responde «SIM» para concordar em receber. Você pode cancelar quando quiser."},{"t":"tag","text":"Salvar o e-mail e a hora do consentimento. Tag: consentimento-newsletter"}]},"appointment-booking":{"en":[{"t":"trigger","text":"Message asks to book an appointment"},{"t":"msg","text":"Hi [name]! What service would you like to book?"},{"t":"msg","text":"Here are the next available times: [slot 1], [slot 2], [slot 3]. Which one works for you?"},{"t":"msg","text":"Yes: \"Booked! [service] on [date] at [time]. Reply CANCEL if you need to change it.\" No: \"That slot was just taken, here are new options: [slots].\""},{"t":"tag","text":"Tag: booked-[service]"}],"ar":[{"t":"trigger","text":"رسالة بتطلب حجز ميعاد"},{"t":"msg","text":"أهلاً [الاسم]! عايز تحجز أنهي خدمة؟"},{"t":"msg","text":"دي أقرب مواعيد متاحة: [ميعاد 1]، [ميعاد 2]، [ميعاد 3]. أنهي أنسب ليك؟"},{"t":"msg","text":"أيوه: \"تم الحجز! [الخدمة] يوم [التاريخ] الساعة [الوقت]. اكتب إلغاء لو عايز تغيّر.\" لأ: \"الميعاد اتحجز، دي خيارات جديدة: [المواعيد].\""},{"t":"tag","text":"وسم: محجوز-[الخدمة]"}],"de":[{"t":"trigger","text":"Nachricht möchte einen Termin buchen"},{"t":"msg","text":"Hallo [Name]! Welche Leistung möchtest du buchen?"},{"t":"msg","text":"Hier sind die nächsten freien Termine: [Slot 1], [Slot 2], [Slot 3]. Welcher passt dir?"},{"t":"msg","text":"Ja: „Gebucht! [Leistung] am [Datum] um [Uhrzeit]. Antworte STORNIEREN, wenn du ihn ändern musst.“ Nein: „Dieser Slot wurde gerade vergeben, hier sind neue Optionen: [Slots].\""},{"t":"tag","text":"Tag: gebucht-[Leistung]"}],"es":[{"t":"trigger","text":"El mensaje pide reservar una cita"},{"t":"msg","text":"¡Hola [nombre]! ¿Qué servicio te gustaría reservar?"},{"t":"msg","text":"Estos son los próximos horarios disponibles: [horario 1], [horario 2], [horario 3]. ¿Cuál te viene bien?"},{"t":"msg","text":"Sí: «¡Reservado! [servicio] el [fecha] a las [hora]. Responde CANCELAR si necesitas cambiarlo.» No: «Ese horario acaba de ocuparse, aquí hay nuevas opciones: [horarios].»"},{"t":"tag","text":"Etiqueta: reservado-[servicio]"}],"fr":[{"t":"trigger","text":"Le message demande à prendre rendez-vous"},{"t":"msg","text":"Bonjour [nom] ! Quel service souhaites-tu réserver ?"},{"t":"msg","text":"Voici les prochains créneaux disponibles : [créneau 1], [créneau 2], [créneau 3]. Lequel te convient ?"},{"t":"msg","text":"Oui : « Réservé ! [service] le [date] à [heure]. Réponds ANNULER si tu dois le changer. » Non : « Ce créneau vient d'être pris, voici de nouvelles options : [créneaux]. »"},{"t":"tag","text":"Tag : réservé-[service]"}],"pt":[{"t":"trigger","text":"Mensagem pede para agendar um horário"},{"t":"msg","text":"Olá [nome]! Qual serviço você gostaria de agendar?"},{"t":"msg","text":"Aqui estão os próximos horários disponíveis: [horário 1], [horário 2], [horário 3]. Qual funciona pra você?"},{"t":"msg","text":"Sim: «Agendado! [serviço] em [data] às [hora]. Responde CANCELAR se precisar mudar.» Não: «Esse horário acabou de ser ocupado, aqui vão novas opções: [horários].»"},{"t":"tag","text":"Tag: agendado-[serviço]"}]},"no-show-rescue":{"en":[{"t":"trigger","text":"Appointment marked as no-show"},{"t":"msg","text":"Hi [name], we missed you today for your [service]. Everything okay?"},{"t":"delay","v":1440},{"t":"msg","text":"If no reply: \"Just checking in, [name]. Reply with a day that works and we will sort it out.\""}],"ar":[{"t":"trigger","text":"ميعاد اتسجل إنه لم يحضر"},{"t":"msg","text":"أهلاً [الاسم]، افتقدناك النهارده في [الخدمة]. كل حاجة تمام؟"},{"t":"delay","v":1440},{"t":"msg","text":"لو مفيش رد: \"بس بطمّن يا [الاسم]. ابعت يوم مناسب وهنظبطه.\""}],"de":[{"t":"trigger","text":"Termin als nicht erschienen markiert"},{"t":"msg","text":"Hallo [Name], wir haben dich heute bei deinem [Leistung] vermisst. Ist alles okay?"},{"t":"delay","v":1440},{"t":"msg","text":"Falls keine Antwort: „Kurze Nachfrage, [Name]. Antworte mit einem Tag, der dir passt, und wir regeln das.“"}],"es":[{"t":"trigger","text":"Cita marcada como inasistencia"},{"t":"msg","text":"Hola [nombre], te extrañamos hoy en tu [servicio]. ¿Todo bien?"},{"t":"delay","v":1440},{"t":"msg","text":"Si no hay respuesta: «Solo pasaba a saludar, [nombre]. Responde con un día que te venga y lo arreglamos.»"}],"fr":[{"t":"trigger","text":"Rendez-vous marqué comme absence"},{"t":"msg","text":"Bonjour [nom], tu nous as manqué aujourd'hui pour ton [service]. Tout va bien ?"},{"t":"delay","v":1440},{"t":"msg","text":"Si pas de réponse : « Petite relance, [nom]. Réponds avec un jour qui t'arrange et on s'occupe du reste. »"}],"pt":[{"t":"trigger","text":"Horário marcado como falta"},{"t":"msg","text":"Olá [nome], sentimos sua falta hoje no seu [serviço]. Tudo bem?"},{"t":"delay","v":1440},{"t":"msg","text":"Se não responder: «Só passando pra saber, [nome]. Responde com um dia que funcione pra você que a gente resolve.»"}]},"waitlist-fill":{"en":[{"t":"trigger","text":"An appointment is cancelled and a slot opens"},{"t":"msg","text":"Hi [name], a slot opened: [service] on [date] at [time]. Want it? Reply \"YES\" within [30] minutes."},{"t":"msg","text":"Yes: \"Booked for you!\" No: offer it to the next person on the list with the same message."},{"t":"tag","text":"Tag: waitlist-filled, and remove the person from the waitlist"}],"ar":[{"t":"trigger","text":"ميعاد اتلغى وفتح خانة فاضية"},{"t":"msg","text":"أهلاً [الاسم]، اتفتح ميعاد: [الخدمة] يوم [التاريخ] الساعة [الوقت]. عايزه؟ اكتب \"أيوه\" خلال [30] دقيقة."},{"t":"msg","text":"أيوه: \"اتحجزلك!\" لأ: اعرضه على اللي بعده في القايمة بنفس الرسالة."},{"t":"tag","text":"وسم: انتظار-اتملى، وشيل الشخص من قايمة الانتظار"}],"de":[{"t":"trigger","text":"Ein Termin wurde abgesagt und ein Slot wird frei"},{"t":"msg","text":"Hallo [Name], ein Slot ist frei geworden: [Leistung] am [Datum] um [Uhrzeit]. Möchtest du ihn? Antworte „JA“ innerhalb von [30] Minuten."},{"t":"msg","text":"Ja: „Für dich gebucht!“ Nein: der nächsten Person auf der Liste mit derselben Nachricht anbieten."},{"t":"tag","text":"Tag: warteliste-gefüllt, und die Person von der Warteliste entfernen"}],"es":[{"t":"trigger","text":"Se cancela una cita y se libera un horario"},{"t":"msg","text":"Hola [nombre], se liberó un horario: [servicio] el [fecha] a las [hora]. ¿Lo quieres? Responde «SÍ» en [30] minutos."},{"t":"msg","text":"Sí: «¡Reservado para ti!» No: ofrecerlo a la siguiente persona de la lista con el mismo mensaje."},{"t":"tag","text":"Etiqueta: lista-cubierta, y quitar a la persona de la lista de espera"}],"fr":[{"t":"trigger","text":"Un rendez-vous est annulé et un créneau se libère"},{"t":"msg","text":"Bonjour [nom], un créneau s'est libéré : [service] le [date] à [heure]. Tu le veux ? Réponds « OUI » dans les [30] minutes."},{"t":"msg","text":"Oui : « Réservé pour toi ! » Non : le proposer à la personne suivante sur la liste avec le même message."},{"t":"tag","text":"Tag : attente-comblée, et retirer la personne de la liste d'attente"}],"pt":[{"t":"trigger","text":"Um horário foi cancelado e uma vaga abriu"},{"t":"msg","text":"Olá [nome], abriu uma vaga: [serviço] em [data] às [hora]. Quer? Responde «SIM» em [30] minutos."},{"t":"msg","text":"Sim: «Agendado pra você!» Não: oferecer para a próxima pessoa da lista com a mesma mensagem."},{"t":"tag","text":"Tag: lista-preenchida, e remover a pessoa da lista de espera"}]},"consultation-upsell":{"en":[{"t":"trigger","text":"Free consultation finished"},{"t":"msg","text":"Thanks for your time today, [name]! As discussed, the best next step is [package], which includes [what is included]."},{"t":"msg","text":"You can start here: [payment link]. Any question about it, just ask."},{"t":"delay","v":2880},{"t":"msg","text":"Gentle follow-up: still thinking about [package]? I am happy to answer questions. Reply STOP to opt out."}],"ar":[{"t":"trigger","text":"الاستشارة المجانية خلصت"},{"t":"msg","text":"شكرًا على وقتك النهارده يا [الاسم]! زي ما اتكلمنا، أنسب خطوة جاية هي [الباقة]، وفيها [المحتويات]."},{"t":"msg","text":"تقدر تبدأ من هنا: [لينك الدفع]. لو عندك أي سؤال اسأل."},{"t":"delay","v":2880},{"t":"msg","text":"متابعة لطيفة: لسه بتفكر في [الباقة]؟ يسعدني أجاوب أسئلتك. اكتب إيقاف لإلغاء الرسايل."}],"de":[{"t":"trigger","text":"Kostenlose Beratung beendet"},{"t":"msg","text":"Danke für deine Zeit heute, [Name]! Wie besprochen ist der beste nächste Schritt [Paket], das beinhaltet [was enthalten ist]."},{"t":"msg","text":"Hier kannst du starten: [Zahlungslink]. Bei Fragen dazu, frag einfach."},{"t":"delay","v":2880},{"t":"msg","text":"Freundliches Nachfassen: Überlegst du noch wegen [Paket]? Ich beantworte gern Fragen. Antworte STOPP zum Abmelden."}],"es":[{"t":"trigger","text":"Consulta gratuita finalizada"},{"t":"msg","text":"¡Gracias por tu tiempo hoy, [nombre]! Como hablamos, el mejor siguiente paso es [paquete], que incluye [qué incluye]."},{"t":"msg","text":"Puedes empezar aquí: [enlace de pago]. Cualquier duda, solo pregunta."},{"t":"delay","v":2880},{"t":"msg","text":"Seguimiento amable: ¿sigues pensándote lo de [paquete]? Encantado de responder dudas. Responde STOP para darte de baja."}],"fr":[{"t":"trigger","text":"Consultation gratuite terminée"},{"t":"msg","text":"Merci pour ton temps aujourd'hui, [nom] ! Comme convenu, la meilleure prochaine étape est [offre], qui comprend [ce qui est inclus]."},{"t":"msg","text":"Tu peux commencer ici : [lien de paiement]. Pour toute question, demande simplement."},{"t":"delay","v":2880},{"t":"msg","text":"Petite relance : tu réfléchis encore à propos de [offre] ? Je réponds volontiers à tes questions. Réponds STOP pour te désinscrire."}],"pt":[{"t":"trigger","text":"Consulta gratuita finalizada"},{"t":"msg","text":"Obrigado pelo seu tempo hoje, [nome]! Como conversamos, o melhor próximo passo é [pacote], que inclui [o que está incluído]."},{"t":"msg","text":"Você pode começar aqui: [link de pagamento]. Qualquer dúvida, é só perguntar."},{"t":"delay","v":2880},{"t":"msg","text":"Follow-up amigável: ainda pensando sobre [pacote]? Respondo dúvidas com prazer. Responde PARAR para sair."}]}};
